def _parse_multiline_items(text):
    """Split textarea content into clean non-empty lines."""
    if not text:
        return []
    items = []
    for line in str(text).replace('\r\n', '\n').replace('\r', '\n').split('\n'):
        cleaned = ' '.join(line.split()).strip(' •-\t')
        if cleaned:
            items.append(cleaned)
    return items


def _parse_firm_core_values(text):
    """Parse core values into title/detail pairs for the About page."""
    items = []
    for raw in _parse_multiline_items(text):
        title, detail = raw, ''
        for sep in (' — ', ' – ', ' - ', ' —', '–', ':'):
            if sep in raw:
                left, right = raw.split(sep, 1)
                if left.strip():
                    title = left.strip()
                    detail = right.strip()
                    break
        items.append({'title': title, 'detail': detail})
    return items


def _firm_holiday_hours_label(firm):
    """Public-holiday opening status from contact settings."""
    status = (firm.get('public_holiday_status') or '').strip()
    if not status:
        return ''
    if status == 'Closed':
        return 'Closed on public holidays'
    open_t = (firm.get('public_holiday_open_time') or '').strip()
    close_t = (firm.get('public_holiday_close_time') or '').strip()
    if status in ('Open', 'Reduced hours') and open_t and close_t:
        label = 'Reduced hours' if status == 'Reduced hours' else 'Open'
        return f'{label} on public holidays · {open_t} – {close_t}'
    return f'{status} on public holidays'


def _firm_payment_methods(firm):
    """M-Pesa payment options for the contact page (when configured)."""
    methods = []
    till = (firm.get('mpesa_till_number') or '').strip()
    paybill = (firm.get('mpesa_paybill_number') or '').strip()
    account = (firm.get('mpesa_paybill_account') or '').strip()
    if till:
        methods.append({'label': 'M-Pesa Till', 'value': till, 'icon': 'fa-mobile-screen'})
    if paybill:
        detail = paybill
        if account:
            detail = f'{paybill} · Account {account}'
        methods.append({'label': 'M-Pesa Paybill', 'value': detail, 'icon': 'fa-building-columns'})
    return methods


def _firm_public_credentials(firm, attorneys=None):
    """Legal & company credentials surfaced on About, Contact, and footer.

    Tax PIN is intentionally omitted — internal use only (CMS v2).
    """
    lead = (firm.get('lead_advocate_name') or '').strip()
    lead_id = firm.get('lead_advocate_employee_id')
    if lead_id and attorneys:
        try:
            lead_id_int = int(lead_id)
        except (TypeError, ValueError):
            lead_id_int = None
        if lead_id_int:
            for emp in attorneys:
                if emp.get('id') == lead_id_int:
                    lead = (emp.get('full_name') or '').strip() or lead
                    break
    return {
        'lead_advocate': lead,
        'law_society': (firm.get('law_society_reg_number') or '').strip(),
        'practicing_certificate': (firm.get('practicing_certificate_number') or '').strip(),
        'bar_association': (firm.get('bar_association_membership') or '').strip(),
        'registration_number': (firm.get('registration_number') or '').strip(),
        'data_protection': (firm.get('data_protection_registration_number') or '').strip(),
        'jurisdictions': (firm.get('jurisdictions_admitted') or '').strip(),
        'malpractice': (
            (firm.get('malpractice_insurance_detail') or '').strip()
            if firm.get('malpractice_insurance_status') else ''
        ),
        'disciplinary': (firm.get('disciplinary_record_statement') or '').strip(),
    }


def _firm_legal_nav_items(firm, firm_url):
    """Footer/legal page links only when policy content exists."""
    items = []
    if (firm.get('privacy_policy') or '').strip():
        items.append({'key': 'privacy', 'label': 'Privacy Policy', 'url': firm_url('privacy')})
    if (firm.get('terms_of_service') or '').strip():
        items.append({'key': 'terms', 'label': 'Terms of Service', 'url': firm_url('terms')})
    if (firm.get('website_disclaimer') or '').strip():
        items.append({'key': 'disclaimer', 'label': 'Disclaimer', 'url': firm_url('disclaimer')})
    if firm.get('accessibility_statement_enabled'):
        items.append({
            'key': 'accessibility',
            'label': 'Accessibility',
            'url': firm_url('accessibility'),
        })
    return items


def _text_excerpt(text, max_len=280):
    """Trim long text for homepage intros."""
    if not text:
        return ''
    cleaned = ' '.join(str(text).split())
    if len(cleaned) <= max_len:
        return cleaned
    snippet = cleaned[:max_len].rsplit(' ', 1)[0]
    return f'{snippet}…'


def _firm_website_theme(firm):
    """Branding tokens from company settings for the public firm site."""
    primary = (firm.get('primary_brand_color') or '#0B1220').strip()
    secondary = (firm.get('secondary_color') or '#C4A574').strip()
    tertiary = (firm.get('tertiary_color') or '#E2D2B5').strip()
    font_body = (firm.get('font_family') or 'Figtree').strip()
    # Prefer modern editorial type for the public firm site over generic UI stacks.
    if font_body in ('Inter', 'Roboto', 'Open Sans', 'Arial', 'system', 'Source Sans 3'):
        font_body = 'Figtree'
    serif_fonts = {
        'Merriweather', 'Lora', 'Source Serif 4', 'Playfair Display',
        'Cormorant Garamond', 'Libre Baskerville', 'Instrument Serif', 'Newsreader',
    }
    font_heading = font_body if font_body in serif_fonts else 'Instrument Serif'
    return {
        'primary': primary,
        'secondary': secondary,
        'tertiary': tertiary,
        'font_body': font_body,
        'font_heading': font_heading,
        'base_font_size': resolve_app_base_font_size(firm),
        'font_size_id': (firm.get('font_size') or 'comfortable'),
    }


def _firm_trust_badges(firm, awards):
    """Trust signals for the homepage from legal credentials and firm stats."""
    badges = []
    show_lsk = firm.get('homepage_show_trust_lsk', 1)
    show_years = firm.get('homepage_show_trust_years', 1)
    show_cases = firm.get('homepage_show_trust_cases', 1)
    if show_lsk and (firm.get('law_society_reg_number') or '').strip():
        badges.append({
            'icon': 'fa-certificate',
            'label': 'LSK Registered',
            'detail': firm.get('law_society_reg_number'),
        })
    if (firm.get('bar_association_membership') or '').strip():
        badges.append({
            'icon': 'fa-scale-balanced',
            'label': 'Bar Association',
            'detail': firm.get('bar_association_membership'),
        })
    if (firm.get('year_established') or '').strip():
        badges.append({
            'icon': 'fa-landmark',
            'label': f'Est. {firm.get("year_established")}',
            'detail': 'Trusted local advocates',
        })
    if show_years and (firm.get('years_collective_experience') or '').strip():
        badges.append({
            'icon': 'fa-briefcase',
            'label': f'{firm.get("years_collective_experience")}+ Years',
            'detail': 'Collective experience',
        })
    if show_cases and (firm.get('cases_handled_count') or '').strip():
        badges.append({
            'icon': 'fa-gavel',
            'label': f'{firm.get("cases_handled_count")}+ Cases',
            'detail': 'Matters handled',
        })
    for award in (awards or [])[:1]:
        title = (award.get('title') or '').strip()
        if title:
            badges.append({
                'icon': 'fa-award',
                'label': title,
                'detail': (award.get('year') or '').strip() or 'Recognition',
            })
    return badges[:5]


def _resolve_featured_practice_areas(practice_areas, firm):
    """Homepage featured practice areas from settings (max 3)."""
    ids_raw = (firm.get('homepage_featured_pa_ids') or '').strip()
    if ids_raw:
        id_order = [x.strip() for x in ids_raw.split(',') if x.strip()]
        by_id = {str(pa.get('id')): pa for pa in practice_areas}
        featured = [by_id[pid] for pid in id_order if pid in by_id]
        if featured:
            return featured[:3]
    return practice_areas[:3]


def _firm_cta_label(firm, practice_area=None):
    if practice_area and (practice_area.get('cta_label') or '').strip():
        return practice_area['cta_label'].strip()
    return (firm.get('homepage_cta_label') or 'Book a Free Consultation').strip()


def _firm_consultation_fee_label(firm, practice_area=None):
    if practice_area and practice_area.get('free_consultation'):
        return 'Free consultation'
    if practice_area and (practice_area.get('consultation_fee') or '').strip():
        return practice_area['consultation_fee'].strip()
    if firm.get('default_free_consultation'):
        return 'Free consultation'
    fee = (firm.get('default_consultation_fee') or '').strip()
    return fee or ''


def _firm_response_time_label(firm, practice_area=None):
    if practice_area and (practice_area.get('response_time_commitment') or '').strip():
        return practice_area['response_time_commitment'].strip()
    return (firm.get('consultation_response_time') or '').strip()


def _video_embed_url(url):
    """Convert YouTube/Vimeo share URLs to embed URLs."""
    if not url:
        return ''
    text = str(url).strip()
    if not text:
        return ''
    import re as _re
    yt = _re.search(
        r'(?:youtube\.com/watch\?v=|youtu\.be/|youtube\.com/embed/)([\w-]{11})',
        text,
    )
    if yt:
        return f'https://www.youtube.com/embed/{yt.group(1)}'
    vimeo = _re.search(r'vimeo\.com/(?:video/)?(\d+)', text)
    if vimeo:
        return f'https://player.vimeo.com/video/{vimeo.group(1)}'
    if 'youtube.com/embed' in text or 'player.vimeo.com' in text:
        return text
    return ''


def _firm_website_nav_items(
    practice_areas, attorneys, faqs, testimonials, case_outcomes,
    *, blog_posts=None, careers_content='', preview_mode=False,
):
    """Primary navigation links — omit empty sections."""
    def u(path):
        return _firm_site_path(path, preview_mode)

    items = [
        {'key': 'home', 'label': 'Home', 'url': u('')},
        {'key': 'about', 'label': 'About', 'url': u('about')},
    ]
    if practice_areas:
        items.append({'key': 'practice_areas', 'label': 'Practice Areas', 'url': u('practice-areas')})
    if attorneys:
        items.append({'key': 'team', 'label': 'Our Team', 'url': u('team')})
    if testimonials or case_outcomes:
        items.append({'key': 'results', 'label': 'Results', 'url': u('results')})
    if blog_posts:
        items.append({'key': 'blog', 'label': 'Insights', 'url': u('blog')})
    if faqs:
        items.append({'key': 'faq', 'label': 'FAQ', 'url': u('faq')})
    if careers_content:
        items.append({'key': 'careers', 'label': 'Careers', 'url': u('careers')})
    items.append({'key': 'contact', 'label': 'Contact', 'url': u('contact')})
    return items


def _whatsapp_chat_url(phone_number):
    """Build a WhatsApp click-to-chat URL from a stored phone number."""
    if not phone_number:
        return ''
    import re as _re
    digits = _re.sub(r'\D', '', str(phone_number))
    if not digits:
        return ''
    if digits.startswith('0') and len(digits) >= 10:
        digits = '254' + digits[1:]
    elif len(digits) == 9:
        digits = '254' + digits
    return f'https://wa.me/{digits}'


def _firm_site_path(path='', preview_mode=False):
    """Build a public firm-site path, optionally under /website_preview for staff."""
    path = (path or '').strip('/')
    if preview_mode:
        return f'/website_preview/{path}' if path else '/website_preview'
    return f'/{path}' if path else '/'


def _firm_canonical_url(path=''):
    """Absolute canonical URL for a firm website path."""
    base = get_public_base_url().rstrip('/')
    if not base:
        return ''
    path = (path or '').strip('/')
    return f'{base}/{path}' if path else f'{base}/'


def _practice_area_public_slug(pa):
    return (pa.get('url_slug') or str(pa.get('id') or '')).strip()


def _attorney_public_slug(emp):
    slug = (emp.get('url_slug') or '').strip()
    if slug:
        return slug
    return _slugify_url(emp.get('full_name') or '')


# Public team directory: role hierarchy (Managing Partner first).
_PUBLIC_TEAM_ROLE_ORDER = (
    'Managing Partner',
    'Associate Advocate',
    'Firm Administrator',
    'IT Support',
    'Employee',
    'Finance Office',
    'Clerk',
)
_PUBLIC_TEAM_ROLE_LABELS = {
    'Managing Partner': 'Managing Directors',
    'Associate Advocate': 'Associates',
    'Firm Administrator': 'Firm Administrators',
    'IT Support': 'IT Support',
    'Employee': 'Employees',
    'Finance Office': 'Finance',
    'Clerk': 'Clerks',
}


def _public_team_role_rank(role):
    role = (role or '').strip()
    try:
        return _PUBLIC_TEAM_ROLE_ORDER.index(role)
    except ValueError:
        return len(_PUBLIC_TEAM_ROLE_ORDER)


def _public_team_role_label(role):
    role = (role or '').strip()
    return _PUBLIC_TEAM_ROLE_LABELS.get(role) or role or 'Team'


def _is_public_team_member(emp):
    """True when an employee should appear on the public team directory."""
    status = str((emp or {}).get('status') or '').strip().lower()
    return status in ('', 'active')


def _sort_public_team_members(employees):
    """Order public team: Managing Partner → Associate → Admin → IT → Employee."""
    return sorted(
        employees or [],
        key=lambda e: (
            _public_team_role_rank(e.get('role')),
            (e.get('full_name') or '').lower(),
        ),
    )


def _group_public_team_members(employees):
    """Group sorted public team members by role for sectioned directories."""
    groups = []
    for emp in employees or []:
        role = (emp.get('role') or 'Employee').strip() or 'Employee'
        label = emp.get('team_role_label') or _public_team_role_label(role)
        if not groups or groups[-1]['role'] != role:
            groups.append({'role': role, 'label': label, 'members': []})
        groups[-1]['members'].append(emp)
    return groups


def _find_practice_area(practice_areas, slug):
    if not slug:
        return None
    for pa in practice_areas:
        if _practice_area_public_slug(pa) == slug or str(pa.get('id')) == str(slug):
            return pa
    return None


def _find_attorney(attorneys, slug):
    if not slug:
        return None
    for emp in attorneys:
        if _attorney_public_slug(emp) == slug or str(emp.get('id')) == str(slug):
            return emp
    return None


def _seo_from_practice_area(pa, firm_name):
    slug = _practice_area_public_slug(pa)
    return {
        'meta_title': ((pa.get('meta_title') or f'{pa.get("name")} | {firm_name}') or firm_name)[:70],
        'meta_description': (
            (pa.get('meta_description') or pa.get('short_description') or pa.get('description') or '')[:160]
        ),
        'h1_heading': (pa.get('h1_heading') or pa.get('name') or '').strip(),
        'url_slug': slug,
        'canonical_url': resolve_public_canonical_url(
            pa.get('canonical_url'),
            f'practice-areas/{slug}',
        ),
    }


def _seo_from_attorney(emp, firm_name):
    slug = _attorney_public_slug(emp)
    return {
        'meta_title': ((emp.get('meta_title') or f'{emp.get("full_name")} | {firm_name}') or firm_name)[:70],
        'meta_description': (
            (emp.get('meta_description') or _text_excerpt(emp.get('attorney_bio') or '', 155))[:160]
        ),
        'h1_heading': (emp.get('h1_heading') or emp.get('full_name') or '').strip(),
        'url_slug': slug,
        'canonical_url': resolve_public_canonical_url(
            emp.get('canonical_url'),
            f'team/{slug}',
        ),
    }


def _seo_from_blog_post(post, firm_name):
    slug = (post.get('slug') or '').strip()
    return {
        'meta_title': (post.get('title') or firm_name)[:70],
        'meta_description': (post.get('excerpt') or _text_excerpt(post.get('body') or '', 155))[:160],
        'h1_heading': (post.get('title') or '').strip(),
        'url_slug': slug,
        'canonical_url': _firm_canonical_url(f'blog/{slug}'),
    }


