def _render_firm_website_page(page_key, **extra):
    """Render a firm website page template with shared CMS context."""
    template_name = FIRM_WEBSITE_TEMPLATES.get(page_key)
    if not template_name:
        flash('Page not found.', 'error')
        return redirect(url_for('index'))
    ctx = _get_firm_website_context(page=page_key, **extra)
    return render_template(template_name, **ctx)


def _guard_firm_website_public():
    """Ensure firm website is published for public visitors."""
    auth = _redirect_authenticated_user_from_public_site()
    if auth:
        return auth
    if not is_firm_website_enabled():
        flash('This page is not available.', 'info')
        return redirect(url_for('index'))
    return None


def _dispatch_firm_website_path(subpath='', preview_mode=False):
    """Route a firm website path to the correct page."""
    subpath = (subpath or '').strip('/')
    parts = [p for p in subpath.split('/') if p] if subpath else []

    if not parts:
        return _render_firm_website_page('home', preview_mode=preview_mode)

    head = parts[0]
    if head == 'about':
        return _render_firm_website_page('about', preview_mode=preview_mode)
    if head == 'practice-areas':
        if len(parts) == 1:
            return _render_firm_website_page('practice_areas', preview_mode=preview_mode)
        ctx = _get_firm_website_context(page='practice_area', preview_mode=preview_mode)
        if len(parts) >= 3:
            pa = _find_practice_area(ctx['practice_areas'], parts[1])
            loc_slug = parts[2]
            office = next(
                (o for o in (ctx.get('firm_offices') or []) if o.get('slug') == loc_slug),
                None,
            )
            if pa and office:
                # Local SEO page: /practice-areas/<pa>/<city>
                city = office.get('city') or office.get('county') or office.get('label')
                local_seo = dict(ctx.get('page_seo') or {})
                local_seo['h1_heading'] = f"{pa.get('name')} in {city}"
                local_seo['meta_title'] = _auto_firm_meta_title(
                    local_seo['h1_heading'], ctx.get('firm_name') or ''
                )
                local_seo['meta_description'] = _text_excerpt(
                    pa.get('short_description') or pa.get('description') or '',
                    155,
                ) or f"{pa.get('name')} lawyers serving {city}."
                return _render_firm_website_page(
                    'practice_area',
                    preview_mode=preview_mode,
                    practice_area=pa,
                    local_office=office,
                    page_seo_override=local_seo,
                )
        pa = _find_practice_area(ctx['practice_areas'], parts[1])
        if not pa:
            # Combined slug e.g. family-law-nairobi
            for candidate in ctx['practice_areas']:
                for office in (ctx.get('firm_offices') or []):
                    if _local_practice_page_slug(candidate, office) == parts[1]:
                        city = office.get('city') or office.get('county') or office.get('label')
                        return _render_firm_website_page(
                            'practice_area',
                            preview_mode=preview_mode,
                            practice_area=candidate,
                            local_office=office,
                        )
            flash('Practice area not found.', 'error')
            return redirect(_firm_site_path('practice-areas', preview_mode))
        return _render_firm_website_page('practice_area', preview_mode=preview_mode, practice_area=pa)
    if head == 'accessibility':
        ctx = _get_firm_website_context(page='about', preview_mode=preview_mode)
        if not ctx.get('accessibility_statement_enabled'):
            flash('Page not found.', 'error')
            return redirect(_firm_site_path('', preview_mode))
        return _render_firm_website_page(
            'disclaimer',
            preview_mode=preview_mode,
            legal_page_key='accessibility',
        )
    if head == 'team':
        if len(parts) == 1:
            return _render_firm_website_page('team', preview_mode=preview_mode)
        ctx = _get_firm_website_context(page='attorney', preview_mode=preview_mode)
        emp = _find_attorney(ctx['attorneys'], parts[1])
        if not emp or (emp.get('status') or 'Active') != 'Active':
            flash('Team member not found.', 'error')
            return redirect(_firm_site_path('team', preview_mode))
        return _render_firm_website_page('attorney', preview_mode=preview_mode, attorney=emp)
    if head == 'contact':
        return _firm_contact_handler(preview_mode=preview_mode)
    if head == 'faq':
        return _render_firm_website_page('faq', preview_mode=preview_mode)
    if head == 'results':
        return _render_firm_website_page('results', preview_mode=preview_mode)
    if head == 'blog':
        if len(parts) == 1:
            return _render_firm_website_page('blog', preview_mode=preview_mode)
        connection = get_db_connection()
        post = None
        if connection:
            try:
                post = _fetch_blog_post_by_slug(connection, parts[1])
            finally:
                connection.close()
        if not post:
            flash('Article not found.', 'error')
            return redirect(_firm_site_path('blog', preview_mode))
        return _render_firm_website_page('blog_post', preview_mode=preview_mode, blog_post=post)
    if head == 'careers':
        ctx = _get_firm_website_context(page='careers', preview_mode=preview_mode)
        if not ctx.get('careers_content'):
            flash('Careers page is not available.', 'info')
            return redirect(_firm_site_path('', preview_mode))
        return _render_firm_website_page('careers', preview_mode=preview_mode)
    if head in ('privacy', 'terms', 'disclaimer'):
        return _render_firm_website_page(head, preview_mode=preview_mode, legal_page_key=head)

    flash('Page not found.', 'error')
    return redirect(_firm_site_path('', preview_mode))


def _firm_contact_handler(preview_mode=False):
    """GET/POST contact page for the firm website."""
    form_success = None
    form_error = None
    if request.method == 'POST':
        connection = get_db_connection()
        if not connection:
            form_error = 'Unable to submit your request right now. Please try again later.'
        else:
            try:
                ok, msg = _save_firm_consultation_request(connection, request.form)
                if ok:
                    form_success = msg
                else:
                    form_error = msg
            except Exception as err:
                print(f"Consultation form error: {err}")
                form_error = 'An error occurred while submitting your request.'
            finally:
                connection.close()
    return _render_firm_website_page(
        'contact',
        preview_mode=preview_mode,
        form_success=form_success,
        form_error=form_error,
    )


def _render_sheria_or_firm_public(sheria_template):
    """Render Sheria marketing page or the firm website when that mode is enabled."""
    signed_in_redirect = _redirect_authenticated_user_from_public_site()
    if signed_in_redirect:
        return signed_in_redirect
    if is_firm_website_enabled():
        if request.endpoint != 'index':
            return redirect(url_for('index'))
        return _render_firm_website_page('home')
    return render_template(sheria_template)


COMPANY_ASSET_STATIC_PREFIX = 'uploads/profile_pictures'
DOCUMENT_ASSET_COLUMNS = (
    'default_letterhead',
    'stamp_seal_upload',
    'default_signature_documents',
)


def company_asset_basename(stored_value):
    """Return safe local filename from a company_settings asset value, or None."""
    if not stored_value:
        return None
    text = str(stored_value).strip()
    if not text or text.startswith('http://') or text.startswith('https://'):
        return None
    base = os.path.basename(text.replace('\\', '/'))
    if not base or base in ('.', '..'):
        return None
    return base


def company_asset_public_url(stored_value):
    """Absolute URL for external APIs (e.g. Google Docs). Pass-through if already http(s)."""
    if not stored_value:
        return None
    text = str(stored_value).strip()
    if text.startswith('http://') or text.startswith('https://'):
        return text
    filename = company_asset_basename(text)
    if not filename:
        return None
    base = get_public_base_url()
    if not base:
        return None
    return f"{base}/static/{COMPANY_ASSET_STATIC_PREFIX}/{filename}"


def company_asset_static_path(stored_value):
    """Relative static path segment for url_for('static', filename=...)."""
    filename = company_asset_basename(stored_value)
    if not filename:
        return None
    return f"{COMPANY_ASSET_STATIC_PREFIX}/{filename}"


def process_letterhead_image(image_file):
    """Resize letterhead for storage while preserving full color (no transparency extraction)."""
    try:
        img = Image.open(image_file)
        if img.mode not in ('RGB', 'RGBA'):
            if img.mode == 'P' and 'transparency' in img.info:
                img = img.convert('RGBA')
            else:
                img = img.convert('RGB')
        max_width, max_height = 1200, 320
        if img.width > max_width or img.height > max_height:
            img.thumbnail((max_width, max_height), Image.Resampling.LANCZOS)
        output = BytesIO()
        if img.mode == 'RGBA':
            img.save(output, format='PNG', optimize=True)
            ext = 'png'
        else:
            if img.mode != 'RGB':
                img = img.convert('RGB')
            img.save(output, format='JPEG', optimize=True, quality=90)
            ext = 'jpg'
        output.seek(0)
        return output, ext
    except Exception as e:
        print(f"Error processing letterhead: {e}")
        return None, None


def _google_doc_body_end_index(doc):
    """Last index in document body (for append operations)."""
    return _google_doc_segment_end_index(doc, segment_id=None)


def _google_doc_segment_end_index(doc, segment_id=None):
    """Last index in document body, or in a header/footer segment."""
    if segment_id:
        headers = doc.get('headers') or {}
        footers = doc.get('footers') or {}
        segment = headers.get(segment_id) or footers.get(segment_id) or {}
        default_start = 0
    else:
        segment = doc.get('body') or {}
        default_start = 1
    end_index = default_start
    for el in segment.get('content', []):
        if el.get('endIndex') is not None:
            end_index = max(end_index, el['endIndex'])
    return end_index


# Google Docs inline image sizes (points) for stamp and signature.
GOOGLE_DOC_STAMP_SIZE_PT = (88, 88)
GOOGLE_DOC_SIGNATURE_SIZE_PT = (200, 72)


def _google_doc_ensure_default_header_id(docs_service, file_id):
    """Return the DEFAULT header segment id, creating it when missing."""
    doc = docs_service.documents().get(documentId=file_id).execute()
    header_id = (doc.get('documentStyle') or {}).get('defaultHeaderId')
    if header_id:
        return header_id
    result = docs_service.documents().batchUpdate(
        documentId=file_id,
        body={'requests': [{'createHeader': {'type': 'DEFAULT'}}]},
    ).execute()
    for reply in result.get('replies', []):
        created = reply.get('createHeader') or {}
        if created.get('headerId'):
            return created['headerId']
    doc = docs_service.documents().get(documentId=file_id).execute()
    return (doc.get('documentStyle') or {}).get('defaultHeaderId')


def _google_doc_set_compact_page_margins(docs_service, file_id):
    """Reduce top margin so the header letterhead sits nearer the page top."""
    try:
        docs_service.documents().batchUpdate(
            documentId=file_id,
            body={'requests': [{
                'updateDocumentStyle': {
                    'documentStyle': {
                        'marginTop': {'magnitude': 36, 'unit': 'PT'},
                        'marginHeader': {'magnitude': 12, 'unit': 'PT'},
                    },
                    'fields': 'marginTop,marginHeader',
                },
            }]},
        ).execute()
    except Exception as err:
        print(f"[Docs] Could not update page margins: {err}")


def _google_doc_insert_inline_image(
    docs_service,
    file_id,
    image_url,
    index,
    *,
    segment_id=None,
    width_pt=None,
    height_pt=None,
):
    """Best-effort inline image insert; returns True on success."""
    if not image_url:
        return False
    try:
        min_index = 0 if segment_id else 1
        location = {'index': max(min_index, index)}
        if segment_id:
            location['segmentId'] = segment_id
        image_req = {
            'uri': image_url,
            'location': location,
        }
        if width_pt and height_pt:
            image_req['objectSize'] = {
                'width': {'magnitude': width_pt, 'unit': 'PT'},
                'height': {'magnitude': height_pt, 'unit': 'PT'},
            }
        docs_service.documents().batchUpdate(
            documentId=file_id,
            body={'requests': [{'insertInlineImage': image_req}]},
        ).execute()
        return True
    except Exception as err:
        print(f"Docs API image insert failed ({image_url}): {err}")
        return False


def _is_stamp_or_signature_asset(filename):
    """True for personal/firm stamp or signature image files."""
    if not filename:
        return False
    lower = filename.lower()
    return (
        lower.startswith('signature')
        or lower.startswith('stamp')
        or 'stamp_seal' in lower
    )


def _prepare_image_for_google_docs(local_path, *, stamp_or_signature=False):
    """
    Prepare image bytes for Google Docs/Slides insertInlineImage.
    Stamp/signature: composite on white and crop to dark ink (fixes canvas PNG alpha bugs).
    Other assets: pass through unchanged.
    """
    try:
        img = Image.open(local_path)
        if stamp_or_signature:
            rgba = img.convert('RGBA')
            flat = Image.new('RGB', rgba.size, (255, 255, 255))
            flat.paste(rgba, mask=rgba.split()[3])
            gray = flat.convert('L')
            ink_mask = gray.point(lambda p: 255 if p < 248 else 0, mode='1')
            bbox = ink_mask.getbbox()
            if bbox:
                pad = 6
                left = max(0, bbox[0] - pad)
                top = max(0, bbox[1] - pad)
                right = min(flat.width, bbox[2] + pad)
                bottom = min(flat.height, bbox[3] + pad)
                flat = flat.crop((left, top, right, bottom))
            out = BytesIO()
            flat.save(out, format='PNG', optimize=True)
            out.seek(0)
            return out
        out = BytesIO()
        img.save(out, format='PNG', optimize=True)
        out.seek(0)
        return out
    except Exception as err:
        print(f"[branding] Image prepare failed ({local_path}): {err}")
        return None


def _google_doc_insert_stamp_signature_footer_block(
    docs_service,
    file_id,
    stamp_url,
    signature_url,
):
    """Sign-off at document end: closing line, then stamp and signature with fixed sizes."""
    if not stamp_url and not signature_url:
        return False

    inserted = False
    try:
        doc = docs_service.documents().get(documentId=file_id).execute()
        end_index = max(1, _google_doc_body_end_index(doc) - 1)
        docs_service.documents().batchUpdate(
            documentId=file_id,
            body={'requests': [{
                'insertText': {
                    'location': {'index': end_index},
                    'text': '\n\nYours faithfully,\n\n',
                },
            }]},
        ).execute()

        doc = docs_service.documents().get(documentId=file_id).execute()
        end_index = max(1, _google_doc_body_end_index(doc) - 1)

        if stamp_url:
            ok = _google_doc_insert_inline_image(
                docs_service,
                file_id,
                stamp_url,
                end_index,
                width_pt=GOOGLE_DOC_STAMP_SIZE_PT[0],
                height_pt=GOOGLE_DOC_STAMP_SIZE_PT[1],
            )
            inserted = inserted or ok
            doc = docs_service.documents().get(documentId=file_id).execute()
            end_index = max(1, _google_doc_body_end_index(doc) - 1)
            if signature_url:
                docs_service.documents().batchUpdate(
                    documentId=file_id,
                    body={'requests': [{
                        'insertText': {'location': {'index': end_index}, 'text': '  '},
                    }]},
                ).execute()
                doc = docs_service.documents().get(documentId=file_id).execute()
                end_index = max(1, _google_doc_body_end_index(doc) - 1)

        if signature_url:
            ok = _google_doc_insert_inline_image(
                docs_service,
                file_id,
                signature_url,
                end_index,
                width_pt=GOOGLE_DOC_SIGNATURE_SIZE_PT[0],
                height_pt=GOOGLE_DOC_SIGNATURE_SIZE_PT[1],
            )
            inserted = inserted or ok
    except Exception as err:
        print(f"[Docs] Footer stamp/signature insert failed: {err}")
    return inserted


def _public_base_url_usable_for_google():
    """True when the auto-detected public base URL is reachable by Google's servers."""
    base = get_public_base_url()
    if not base:
        return False
    lowered = base.lower()
    return not (
        lowered.startswith('http://127.0.0.1')
        or lowered.startswith('http://localhost')
        or lowered.startswith('https://127.0.0.1')
        or lowered.startswith('https://localhost')
    )


def _upload_local_asset_to_drive(drive_service, parent_folder_id, stored_value):
    """Upload a company static asset to Drive; return a public HTTPS URI for Docs/Slides."""
    static_rel = company_asset_static_path(stored_value)
    if not static_rel or not drive_service or not parent_folder_id:
        return None
    filename = company_asset_basename(stored_value)
    if not filename:
        return None
    local_path = os.path.join(app.root_path, 'static', static_rel.replace('/', os.sep))
    if not os.path.isfile(local_path):
        return None
    mime_type = mimetypes.guess_type(local_path)[0] or 'image/png'
    is_sign = _is_stamp_or_signature_asset(filename)
    try:
        mtime = int(os.path.getmtime(local_path))
        drive_name = f'branding_{mtime}_{filename}'
        prepared = None
        if filename.lower().endswith('.png'):
            prepared = _prepare_image_for_google_docs(
                local_path, stamp_or_signature=is_sign,
            )
        if prepared:
            media = MediaIoBaseUpload(prepared, mimetype='image/png', resumable=False)
        else:
            with open(local_path, 'rb') as fh:
                media = MediaIoBaseUpload(fh, mimetype=mime_type, resumable=False)
        created = drive_service.files().create(
            body={
                'name': drive_name,
                'parents': [parent_folder_id],
            },
            media_body=media,
            fields='id',
        ).execute()
        drive_file_id = created.get('id')
        if not drive_file_id:
            return None
        try:
            drive_service.permissions().create(
                fileId=drive_file_id,
                body={'type': 'anyone', 'role': 'reader'},
                fields='id',
            ).execute()
        except Exception as perm_err:
            print(f"Branding asset permission warning: {perm_err}")
        # Docs/Slides image fetch works best with direct download URL.
        return f'https://drive.google.com/uc?export=download&id={drive_file_id}'
    except Exception as err:
        print(f"Branding asset Drive upload failed ({filename}): {err}")
        return None


def resolve_company_asset_url_for_google(
    stored_value,
    drive_service=None,
    drive_assets_folder_id=None,
    url_cache=None,
):
    """Resolve an asset to a URL Google's APIs can fetch (public site or Drive-hosted)."""
    if not stored_value:
        return None
    text = str(stored_value).strip()
    if text.startswith('http://') or text.startswith('https://'):
        return text
    cache_key = text
    if url_cache is not None and cache_key in url_cache:
        return url_cache[cache_key]

    url = None
    basename = company_asset_basename(stored_value)
    is_sign = _is_stamp_or_signature_asset(basename)
    if drive_service and drive_assets_folder_id:
        url = _upload_local_asset_to_drive(drive_service, drive_assets_folder_id, stored_value)
    if not url and is_sign and _public_base_url_usable_for_google():
        base = get_public_base_url()
        if base and basename:
            url = f"{base.rstrip('/')}/api/branding-asset/google/{basename}"
    if not url and _public_base_url_usable_for_google():
        url = company_asset_public_url(stored_value)
    if not url and drive_service and drive_assets_folder_id:
        url = _upload_local_asset_to_drive(drive_service, drive_assets_folder_id, stored_value)

    if url_cache is not None:
        url_cache[cache_key] = url
    return url


def _wait_for_google_doc(docs_service, file_id, attempts=6):
    """Retry until a newly created Doc is readable via the Docs API."""
    last_err = None
    for attempt in range(attempts):
        try:
            return docs_service.documents().get(documentId=file_id).execute()
        except HttpError as err:
            last_err = err
            if err.resp.status in (404, 503, 500) and attempt < attempts - 1:
                time.sleep(0.35 * (attempt + 1))
                continue
            raise
    if last_err:
        raise last_err
    return None


def _google_docs_api_error_message(err, *, app_label='document'):
    """Human-readable message from a Docs/Slides HttpError."""
    if isinstance(err, HttpError):
        status = err.resp.status
        if status == 403:
            return (
                'Google Drive needs permission to edit documents. Disconnect and reconnect '
                'Google Drive in Documents Settings (grant all requested permissions).'
            )
        if status == 404:
            return f'The Google {app_label} was not ready yet. Please try again in a few seconds.'
        detail = getattr(err, 'error_details', None) or str(err)
        return f'Google {app_label} error ({status}): {detail}'
    return str(err)


def apply_google_doc_company_branding(
    docs_service,
    file_id,
    company_settings,
    company_name,
    employee_name,
    employee_signature_file=None,
    employee_stamp_file=None,
    drive_service=None,
    drive_assets_folder_id=None,
):
    """
    Apply firm letterhead, logo, header/footer text, stamp, and signature to a new Google Doc.
    Employee stamp/signature override firm defaults when provided.
    Returns (content_added: bool, warning_message: str|None).
    """
    if not company_settings:
        return False, None

    warning = None
    content_added = False
    company_name = (company_name or company_settings.get('company_name') or 'Law Firm').strip()
    employee_name = (employee_name or 'N/A').strip()
    url_cache = {}

    def asset_url(stored):
        return resolve_company_asset_url_for_google(
            stored,
            drive_service=drive_service,
            drive_assets_folder_id=drive_assets_folder_id,
            url_cache=url_cache,
        )

    def resolve_stamp_or_signature(primary, company_field):
        for stored in (primary, company_settings.get(company_field)):
            if not stored:
                continue
            url = asset_url(stored)
            if url:
                return url
        return None

    letterhead_url = asset_url(company_settings.get('default_letterhead'))
    logo_url = asset_url(company_settings.get('company_logo'))
    stamp_url = resolve_stamp_or_signature(employee_stamp_file, 'stamp_seal_upload')
    signature_url = resolve_stamp_or_signature(
        employee_signature_file, 'default_signature_documents'
    )

    if not _public_base_url_usable_for_google() and not drive_service:
        if any(
            company_settings.get(k)
            for k in DOCUMENT_ASSET_COLUMNS + ('company_logo',)
        ):
            warning = (
                'Images may be missing on localhost — connect Google Drive so assets upload '
                'to Drive automatically, or deploy on a public HTTPS domain.'
            )
    elif (company_settings.get('stamp_seal_upload') or company_settings.get('default_signature_documents')):
        missing = []
        if company_settings.get('stamp_seal_upload') and not stamp_url:
            missing.append('stamp')
        if company_settings.get('default_signature_documents') and not signature_url:
            missing.append('signature')
        if missing:
            extra = (
                ' Could not embed firm ' + ' and '.join(missing)
                + ' — reconnect Google Drive or use a public HTTPS domain.'
            )
            warning = (warning or '') + extra

    _wait_for_google_doc(docs_service, file_id)
    _google_doc_set_compact_page_margins(docs_service, file_id)

    # Letterhead strip → document HEADER (top of every page). Body stays empty for typing.
    letterhead_width_pt = 468   # ~6.5 in page width
    letterhead_height_pt = 84     # header strip aspect ratio

    if letterhead_url:
        header_id = _google_doc_ensure_default_header_id(docs_service, file_id)
        if header_id:
            content_added = _google_doc_insert_inline_image(
                docs_service,
                file_id,
                letterhead_url,
                0,
                segment_id=header_id,
                width_pt=letterhead_width_pt,
                height_pt=letterhead_height_pt,
            )
        if not content_added:
            content_added = _google_doc_insert_inline_image(
                docs_service,
                file_id,
                letterhead_url,
                1,
                width_pt=letterhead_width_pt,
                height_pt=letterhead_height_pt,
            )
    elif logo_url:
        content_added = _google_doc_insert_inline_image(
            docs_service, file_id, logo_url, 1, width_pt=120, height_pt=48,
        )
    else:
        date_str = datetime.now().strftime('%Y-%m-%d')
        header_text = "\n".join([
            company_name,
            f"Prepared by: {employee_name}",
            f"Date: {date_str}",
            "",
            "",
        ])
        docs_service.documents().batchUpdate(
            documentId=file_id,
            body={'requests': [{'insertText': {'location': {'index': 1}, 'text': header_text}}]},
        ).execute()
        content_added = True

    if content_added:
        docs_service.documents().batchUpdate(
            documentId=file_id,
            body={'requests': [{'insertText': {'location': {'index': 1}, 'text': '\n'}}]},
        ).execute()

    footer_text = (company_settings.get('document_footer_text') or '').strip()
    if footer_text:
        doc = docs_service.documents().get(documentId=file_id).execute()
        footer_index = max(1, _google_doc_body_end_index(doc) - 1)
        docs_service.documents().batchUpdate(
            documentId=file_id,
            body={'requests': [{'insertText': {
                'location': {'index': footer_index},
                'text': '\n\n' + footer_text,
            }}]},
        ).execute()

    # Sign-off block at document end (stamp then signature).
    if stamp_url or signature_url:
        if _google_doc_insert_stamp_signature_footer_block(
            docs_service, file_id, stamp_url, signature_url
        ):
            content_added = True

    return content_added, warning


def _slides_pt(magnitude):
    return {'magnitude': magnitude, 'unit': 'PT'}


def _slides_transform(translate_x, translate_y, scale_x=1, scale_y=1):
    return {
        'scaleX': scale_x,
        'scaleY': scale_y,
        'translateX': translate_x,
        'translateY': translate_y,
        'unit': 'PT',
    }


def apply_google_slides_company_branding(
    slides_service,
    presentation_id,
    company_settings,
    company_name,
    employee_name,
    employee_signature_file=None,
    employee_stamp_file=None,
    drive_service=None,
    drive_assets_folder_id=None,
):
    """Apply firm letterhead, logo, text, stamp, and signature on the first slide."""
    if not company_settings:
        return False, None

    warning = None
    company_name = (company_name or company_settings.get('company_name') or 'Law Firm').strip()
    employee_name = (employee_name or 'N/A').strip()
    url_cache = {}

    def asset_url(stored):
        return resolve_company_asset_url_for_google(
            stored,
            drive_service=drive_service,
            drive_assets_folder_id=drive_assets_folder_id,
            url_cache=url_cache,
        )

    def resolve_stamp_or_signature(primary, company_field):
        for stored in (primary, company_settings.get(company_field)):
            if not stored:
                continue
            url = asset_url(stored)
            if url:
                return url
        return None

    letterhead_url = asset_url(company_settings.get('default_letterhead'))
    logo_url = asset_url(company_settings.get('company_logo'))
    stamp_url = resolve_stamp_or_signature(employee_stamp_file, 'stamp_seal_upload')
    signature_url = resolve_stamp_or_signature(
        employee_signature_file, 'default_signature_documents'
    )

    if not _public_base_url_usable_for_google() and not drive_service:
        if any(
            company_settings.get(k)
            for k in DOCUMENT_ASSET_COLUMNS + ('company_logo',)
        ):
            warning = (
                'Images may be missing on localhost — connect Google Drive so assets upload '
                'to Drive automatically, or deploy on a public HTTPS domain.'
            )

    pres = slides_service.presentations().get(presentationId=presentation_id).execute()
    slides = pres.get('slides', [])
    if not slides:
        return False, warning
    slide_id = slides[0]['objectId']

    uid = uuid.uuid4().hex[:10]
    title_shape_id = f'brandingTitle_{uid}'
    requests = []
    y_pos = 24.0

    if letterhead_url:
        requests.append({
            'createImage': {
                'url': letterhead_url,
                'elementProperties': {
                    'pageObjectId': slide_id,
                    'size': {'width': _slides_pt(648), 'height': _slides_pt(96)},
                    'transform': _slides_transform(36, y_pos),
                },
            }
        })
        y_pos += 104.0
    if logo_url:
        requests.append({
            'createImage': {
                'url': logo_url,
                'elementProperties': {
                    'pageObjectId': slide_id,
                    'size': {'width': _slides_pt(72), 'height': _slides_pt(72)},
                    'transform': _slides_transform(36, y_pos),
                },
            }
        })
        y_pos += 80.0

    date_str = datetime.now().strftime('%Y-%m-%d')
    body_text = f"{company_name}\nPrepared by: {employee_name}\nDate: {date_str}"
    text_y = y_pos if letterhead_url or logo_url else 36.0
    requests.extend([
        {
            'createShape': {
                'objectId': title_shape_id,
                'shapeType': 'TEXT_BOX',
                'elementProperties': {
                    'pageObjectId': slide_id,
                    'size': {'width': _slides_pt(520), 'height': _slides_pt(72)},
                    'transform': _slides_transform(120 if logo_url else 36, text_y),
                },
            }
        },
        {'insertText': {'objectId': title_shape_id, 'insertionIndex': 0, 'text': body_text}},
    ])

    footer_text = (company_settings.get('document_footer_text') or '').strip()
    if footer_text:
        footer_shape_id = f'brandingFooter_{uid}'
        requests.extend([
            {
                'createShape': {
                    'objectId': footer_shape_id,
                    'shapeType': 'TEXT_BOX',
                    'elementProperties': {
                        'pageObjectId': slide_id,
                        'size': {'width': _slides_pt(648), 'height': _slides_pt(36)},
                        'transform': _slides_transform(36, 468),
                    },
                }
            },
            {'insertText': {'objectId': footer_shape_id, 'insertionIndex': 0, 'text': footer_text}},
        ])

    sign_y = 340.0
    if stamp_url:
        requests.append({
            'createImage': {
                'url': stamp_url,
                'elementProperties': {
                    'pageObjectId': slide_id,
                    'size': {'width': _slides_pt(96), 'height': _slides_pt(96)},
                    'transform': _slides_transform(36, sign_y),
                },
            }
        })
        sign_y += 104.0
    if signature_url:
        requests.append({
            'createImage': {
                'url': signature_url,
                'elementProperties': {
                    'pageObjectId': slide_id,
                    'size': {'width': _slides_pt(180), 'height': _slides_pt(64)},
                    'transform': _slides_transform(36, sign_y),
                },
            }
        })

    if not requests:
        return False, warning
    try:
        slides_service.presentations().batchUpdate(
            presentationId=presentation_id,
            body={'requests': requests},
        ).execute()
        return True, warning
    except Exception as err:
        print(f"Slides branding failed: {err}")
        return False, warning


@app.context_processor
def inject_global_theme_settings():
    """Inject company settings into all templates for consistent theming."""
    settings = get_company_settings()
    if not settings:
        settings = {'company_name': 'SHERIA LAW FIRM'}
    else:
        # Merge SEO / image-alt fields used by branding + login backgrounds
        try:
            settings = _enrich_company_settings_with_site_meta(dict(settings))
        except Exception as enrich_err:
            print(f"Warning enriching company settings for templates: {enrich_err}")
    section_key = None
    if request.endpoint == 'system_settings_section':
        section_key = (request.view_args or {}).get('section')
    elif request.endpoint == 'company_information':
        section_key = 'company'
    elif request.endpoint in ('system_settings_letterhead', 'system_settings_asset_scan', 'system_settings_asset_capture'):
        section_key = 'documents'
    return {
        'company_settings': settings,
        'app_base_font_size': resolve_app_base_font_size(settings),
        'app_font_size_id': (settings.get('font_size') or 'comfortable'),
        'APP_FONT_SIZE_PRESETS': APP_FONT_SIZE_PRESETS,
        'SYSTEM_SETTINGS_NAV': SYSTEM_SETTINGS_SECTIONS,
        'COMPANY_INFORMATION_SECTION': COMPANY_INFORMATION_SECTION,
        'COMPANY_TEMPLATES_SECTION': COMPANY_TEMPLATES_SECTION,
        'WEBSITE_TEMPLATES_SECTION': WEBSITE_TEMPLATES_SECTION,
        'settings_section_key': section_key,
        'company_asset_static_path': company_asset_static_path,
        'company_asset_basename': company_asset_basename,
        'app_base_url': get_public_base_url(),
    }


@app.context_processor
def inject_role_slug_helpers():
    """Expose the active role slug + helpers to all templates.

    Templates can use:
        {{ current_role_slug }}                          -> 'managing-partner'
        {{ role_to_slug('Firm Administrator') }}         -> 'firm-administrator'
        {{ role_url('employee_management') }}            -> '/managing-partner/employee_management'
        {{ url_for('dashboard', role_slug=current_role_slug) }}

    ``role_url`` is the recommended helper for in-app links — it produces
    URLs that are already role-prefixed for the active session, avoiding
    the 302 hop that ``url_for`` would otherwise trigger.
    """
    try:
        active_slug = current_role_slug()
    except Exception:
        active_slug = 'employee'

    def role_url(endpoint, **values):
        """url_for with the active role slug prepended for employee URLs."""
        try:
            base = url_for(endpoint, **values)
        except Exception:
            return '#'
        if 'employee_id' not in session:
            return base
        if not _is_role_prefixable(base):
            return base
        # Don't double-prefix if the URL already has a role slug
        # (e.g. when called with role_slug=... explicitly).
        for slug in SLUG_TO_ROLE:
            if base.startswith('/' + slug + '/') or base == '/' + slug:
                return base
        return '/' + active_slug + base

    return {
        'current_role_slug': active_slug,
        'role_to_slug': role_to_slug,
        'role_url': role_url,
    }


@app.context_processor
def inject_nav_back_url():
    """Previous page for header Back controls (app shell + firm website).

    Computed against the current request before after_request appends/truncates
    the stack, so Back always points at the real prior page — not browser history.
    """
    history = list(session.get('nav_history') or [])
    try:
        here = _nav_history_full_path()
    except Exception:
        here = None
    back_url = None
    if here and here in history:
        idx = len(history) - 1 - history[::-1].index(here)
        prior = history[:idx]
        back_url = prior[-1] if prior else None
    elif history:
        back_url = history[-1]
    return {'nav_back_url': back_url}

# ==================== WHATSAPP CLOUD API HELPERS ====================

def get_whatsapp_settings():
    """Retrieve active WhatsApp settings from the database"""
    try:
        connection = get_db_connection()
        if not connection:
            return None
        with connection.cursor(pymysql.cursors.DictCursor) as cursor:
            cursor.execute("SELECT * FROM whatsapp_settings WHERE is_active = 1 ORDER BY id DESC LIMIT 1")
            return cursor.fetchone()
    except Exception as e:
        print(f"Error getting WhatsApp settings: {e}")
        return None
    finally:
        if connection:
            connection.close()


def send_whatsapp_message(to_phone, text_body, settings=None):
    """Send a text message via the WhatsApp Cloud API.
    Returns (success: bool, wa_message_id_or_error: str)
    """

    if not settings:
        settings = get_whatsapp_settings()
    if not settings:
        return False, 'WhatsApp not configured'

    # Normalise phone: strip spaces/dashes, ensure leading +
    phone = to_phone.strip().replace(' ', '').replace('-', '')
    if not phone.startswith('+'):
        phone = '+' + phone

    url = f"https://graph.facebook.com/{settings['api_version']}/{settings['phone_number_id']}/messages"
    headers = {
        'Authorization': f"Bearer {settings['access_token']}",
        'Content-Type': 'application/json'
    }
    payload = {
        'messaging_product': 'whatsapp',
        'recipient_type': 'individual',
        'to': phone.lstrip('+'),
        'type': 'text',
        'text': {'preview_url': False, 'body': text_body}
    }

    try:
        resp = requests.post(url, json=payload, headers=headers, timeout=15)
        data = resp.json()
        if resp.status_code in (200, 201) and 'messages' in data:
            wa_id = data['messages'][0].get('id', '')
            return True, wa_id
        error_msg = data.get('error', {}).get('message', resp.text[:200])
        print(f"WhatsApp API error: {error_msg}")
        return False, error_msg
    except Exception as e:
        print(f"WhatsApp send exception: {e}")
        return False, str(e)


def send_whatsapp_media(to_phone, media_url, caption='', media_type='document', settings=None):
    """Send an image or document via WhatsApp Cloud API."""

    if not settings:
        settings = get_whatsapp_settings()
    if not settings:
        return False, 'WhatsApp not configured'

    phone = to_phone.strip().replace(' ', '').replace('-', '')
    if not phone.startswith('+'):
        phone = '+' + phone

    url = f"https://graph.facebook.com/{settings['api_version']}/{settings['phone_number_id']}/messages"
    headers = {
        'Authorization': f"Bearer {settings['access_token']}",
        'Content-Type': 'application/json'
    }

    # media_type should be 'image' or 'document'
    media_obj = {'link': media_url}
    if caption:
        media_obj['caption'] = caption
    if media_type == 'document':
        media_obj['filename'] = caption or 'attachment'

    payload = {
        'messaging_product': 'whatsapp',
        'recipient_type': 'individual',
        'to': phone.lstrip('+'),
        'type': media_type,
        media_type: media_obj
    }

    try:
        resp = requests.post(url, json=payload, headers=headers, timeout=30)
        data = resp.json()
        if resp.status_code in (200, 201) and 'messages' in data:
            return True, data['messages'][0].get('id', '')
        error_msg = data.get('error', {}).get('message', resp.text[:200])
        print(f"WhatsApp media API error: {error_msg}")
        return False, error_msg
    except Exception as e:
        print(f"WhatsApp media send exception: {e}")
        return False, str(e)


