def send_sms(to_phone, text_body, settings=None):
    """Send an SMS via the configured provider.
    Returns (success: bool, result_or_error: str)
    """
    if not settings:
        settings = get_sms_settings()
    if not settings:
        return False, 'SMS not configured'

    provider = settings.get('provider', '')
    api_key = settings.get('api_key', '')
    api_secret = settings.get('api_secret', '')
    sender_id = settings.get('sender_id', '')
    username = settings.get('username', '')
    country_code = settings.get('default_country_code', '+254')

    # Normalise phone
    phone = to_phone.strip().replace(' ', '').replace('-', '')
    if not phone.startswith('+') and not phone.startswith('0'):
        phone = country_code + phone
    elif phone.startswith('0'):
        phone = country_code + phone[1:]

    try:
        if provider == 'africas_talking':
            return _send_sms_africas_talking(phone, text_body, api_key, username, sender_id)
        elif provider == 'twilio':
            return _send_sms_twilio(phone, text_body, api_key, api_secret, sender_id)
        elif provider == 'vonage':
            return _send_sms_vonage(phone, text_body, api_key, api_secret, sender_id)
        elif provider == 'custom':
            custom_url = settings.get('custom_api_url', '')
            return _send_sms_custom(phone, text_body, api_key, api_secret, sender_id, custom_url)
        else:
            return False, f'Unknown SMS provider: {provider}'
    except Exception as e:
        print(f"SMS send exception: {e}")
        return False, str(e)


def _send_sms_africas_talking(phone, text, api_key, username, sender_id):
    """Send SMS via Africa's Talking API"""
    url = 'https://api.africastalking.com/version1/messaging'
    if username == 'sandbox':
        url = 'https://api.sandbox.africastalking.com/version1/messaging'

    headers = {
        'apiKey': api_key,
        'Content-Type': 'application/x-www-form-urlencoded',
        'Accept': 'application/json'
    }
    data = {
        'username': username,
        'to': phone,
        'message': text,
    }
    if sender_id:
        data['from'] = sender_id

    resp = requests.post(url, headers=headers, data=data, timeout=15)
    result = resp.json()

    recipients = result.get('SMSMessageData', {}).get('Recipients', [])
    if recipients:
        status = recipients[0].get('status', '')
        msg_id = recipients[0].get('messageId', '')
        if status == 'Success':
            return True, msg_id
        return False, f"AT status: {status} — {recipients[0].get('statusCode', '')}"

    error_msg = result.get('SMSMessageData', {}).get('Message', resp.text[:200])
    return False, error_msg


def _send_sms_twilio(phone, text, account_sid, auth_token, from_number):
    """Send SMS via Twilio API"""
    url = f'https://api.twilio.com/2010-04-01/Accounts/{account_sid}/Messages.json'
    data = {
        'To': phone,
        'From': from_number,
        'Body': text,
    }
    resp = requests.post(url, data=data, auth=(account_sid, auth_token), timeout=15)
    result = resp.json()
    if resp.status_code in (200, 201):
        return True, result.get('sid', '')
    return False, result.get('message', resp.text[:200])


def _send_sms_vonage(phone, text, api_key, api_secret, sender_id):
    """Send SMS via Vonage (Nexmo) API"""
    url = 'https://rest.nexmo.com/sms/json'
    payload = {
        'api_key': api_key,
        'api_secret': api_secret,
        'to': phone.lstrip('+'),
        'from': sender_id or 'SHERIA',
        'text': text,
    }
    resp = requests.post(url, json=payload, timeout=15)
    result = resp.json()
    msgs = result.get('messages', [])
    if msgs and msgs[0].get('status') == '0':
        return True, msgs[0].get('message-id', '')
    error = msgs[0].get('error-text', resp.text[:200]) if msgs else resp.text[:200]
    return False, error


def _send_sms_custom(phone, text, api_key, api_secret, sender_id, custom_url):
    """Send SMS via a custom API endpoint (POST JSON)"""
    if not custom_url:
        return False, 'Custom API URL not set'
    headers = {
        'Authorization': f'Bearer {api_key}',
        'Content-Type': 'application/json'
    }
    payload = {
        'to': phone,
        'message': text,
        'from': sender_id,
        'api_key': api_key,
        'api_secret': api_secret,
    }
    resp = requests.post(custom_url, json=payload, headers=headers, timeout=15)
    if resp.status_code in (200, 201):
        try:
            data = resp.json()
            return True, data.get('id', data.get('message_id', 'OK'))
        except Exception:
            return True, 'OK'
    return False, resp.text[:200]


# ----------------------------------------------------------------------
# PWA endpoints
# ----------------------------------------------------------------------
# Browsers require the service worker to be served from a path that
# covers the scopes it controls. Serving sw.js from /sw.js (instead of
# /static/sw.js) lets a single worker control the whole site.
# The manifest is served at root for the same reason; some browsers
# look up icons relative to the manifest's URL.

@app.route('/sw.js')
def pwa_service_worker():
    """Serve the service-worker script from the site root so its default
    scope is '/'. We add ``Service-Worker-Allowed: /`` defensively, in
    case the file gets cached behind a CDN that already constrains
    scope."""
    response = send_from_directory(app.static_folder, 'sw.js', mimetype='application/javascript')
    response.headers['Service-Worker-Allowed'] = '/'
    response.headers['Cache-Control'] = 'no-cache, no-store, must-revalidate'
    return response


@app.route('/manifest.webmanifest')
def pwa_manifest():
    """Serve the PWA manifest at the site root with the correct MIME type."""
    response = send_from_directory(
        app.static_folder, 'manifest.webmanifest',
        mimetype='application/manifest+json'
    )
    response.headers['Cache-Control'] = 'public, max-age=86400'
    return response


@app.route('/manifest.json')
def pwa_manifest_alias():
    """Legacy alias — some older tooling expects manifest.json."""
    return pwa_manifest()


@app.route('/favicon.ico')
def pwa_favicon():
    """Most browsers still probe /favicon.ico; serve our PNG favicon."""
    return send_from_directory(
        app.static_folder, 'favicon-32.png', mimetype='image/png'
    )


@app.route('/favicon.svg')
def pwa_favicon_svg():
    """Modern browsers prefer the SVG favicon — they scale it crisply."""
    return send_from_directory(
        app.static_folder, 'favicon.svg', mimetype='image/svg+xml'
    )


@app.route('/apple-touch-icon.png')
@app.route('/apple-touch-icon-precomposed.png')
def pwa_apple_touch_icon():
    """iOS Safari auto-probes these paths when a user adds to Home Screen."""
    return send_from_directory(
        app.static_folder, 'apple-touch-icon.png', mimetype='image/png'
    )


