@app.before_request
def _enforce_endpoint_permissions():
    """Block any mapped endpoint when the employee permission toggle is off."""
    if 'employee_id' not in session:
        return None
    endpoint = request.endpoint
    if not endpoint:
        return None
    permission_key = ENDPOINT_PERMISSION_MAP.get(endpoint)
    if not permission_key:
        return None

    connection = get_db_connection()
    if not connection:
        return None
    try:
        if current_user_has_permission(connection, permission_key):
            return None
        return permission_denied_response(permission_key)
    finally:
        connection.close()


@app.context_processor
def inject_user_permissions():
    """Expose has_perm() / user_permissions to all templates for UI gating."""
    def has_perm(permission_key):
        if 'employee_id' not in session:
            return True
        if permission_key not in PERMISSION_KEYS:
            return True
        permissions = _load_session_permissions_map()
        if permission_key not in permissions:
            return True
        return bool(permissions[permission_key])

    permissions = {}
    if 'employee_id' in session:
        permissions = _load_session_permissions_map()
    return {
        'has_perm': has_perm,
        'user_permissions': permissions,
        'PERMISSION_KEYS': PERMISSION_KEYS,
    }


@app.route('/employee_permissions', methods=['GET', 'POST'])
def employee_permissions():
    """Employee Permissions overview page"""
    if 'employee_id' not in session:
        return redirect(url_for('login'))
    
    user_role = session.get('employee_role')
    original_role = session.get('original_role')
    allowed_roles = ['IT Support', 'Firm Administrator', 'Managing Partner']
    has_permission = (user_role in allowed_roles) or (original_role == 'IT Support')
    
    if not has_permission:
        flash('You do not have permission to access this page', 'error')
        return redirect(url_for('dashboard'))
    
    employee_id = request.args.get('employee_id')
    if not employee_id:
        flash('Employee not specified.', 'error')
        return redirect(url_for('hr_roles_permissions'))
    
    connection = get_db_connection()
    if not connection:
        flash('Database connection error.', 'error')
        return redirect(url_for('dashboard'))
    
    try:
        company_settings = get_company_settings()
        if not company_settings:
            company_settings = {'company_name': 'SHERIA LAW FIRM'}
        
        with connection.cursor(pymysql.cursors.DictCursor) as cursor:
            cursor.execute(
                """
                SELECT 
                    id,
                    full_name,
                    phone_number,
                    work_email,
                    employee_code,
                    role,
                    status,
                    profile_picture
                FROM employees
                WHERE id = %s
                """,
                (employee_id,),
            )
            employee = cursor.fetchone()

        if not employee:
            flash('Employee not found.', 'error')
            return redirect(url_for('hr_roles_permissions'))

        # If form was submitted, save permissions
        if request.method == 'POST':
            save_employee_permissions(connection, employee['id'], request.form)
            flash('Permissions updated for this employee.', 'success')

        # Load permissions map (after any updates)
        permissions_map = get_employee_permissions_map(connection, employee['id'])

        return render_template(
            'employee_permissions.html',
            company_settings=company_settings,
            employee=employee,
            permissions=permissions_map,
        )
    except Exception as e:
        print(f"Employee permissions error: {e}")
        flash('An error occurred while loading employee permissions.', 'error')
        return redirect(url_for('hr_roles_permissions'))
    finally:
        connection.close()

