def _send_employee_document_action_code(employee_id):
    """Load employee and send a verification code email. Returns (delivery_email, error)."""
    connection = get_db_connection()
    if not connection:
        return None, 'Database connection error'
    try:
        with connection.cursor(pymysql.cursors.DictCursor) as cursor:
            cursor.execute("""
                SELECT id, full_name, work_email, personal_email
                FROM employees WHERE id = %s
            """, (employee_id,))
            employee = cursor.fetchone()
            if not employee:
                return None, 'Employee not found'
            delivery_email = (employee.get('personal_email') or employee.get('work_email') or '').strip()
            if not delivery_email:
                return None, 'No registered email on your account. Contact your administrator.'
            return employee, None
    finally:
        connection.close()


def get_or_create_folder(service, parent_folder_id, folder_name):
    """Get or create a folder in Google Drive"""
    try:
        # Escape single quotes in folder name for query
        escaped_folder_name = folder_name.replace("'", "\\'")
        
        # Search for existing folder
        query = f"name='{escaped_folder_name}' and '{parent_folder_id}' in parents and mimeType='application/vnd.google-apps.folder' and trashed=false"
        results = service.files().list(q=query, spaces='drive', fields='files(id, name)').execute()
        folders = results.get('files', [])
        
        if folders:
            return folders[0]['id']
        
        # Create folder if it doesn't exist
        file_metadata = {
            'name': folder_name,
            'mimeType': 'application/vnd.google-apps.folder',
            'parents': [parent_folder_id]
        }
        folder = service.files().create(body=file_metadata, fields='id, name').execute()
        return folder.get('id')
    except Exception as e:
        print(f"Error getting/creating folder {folder_name}: {e}")
        raise


def _grant_drive_file_editor(service, file_id, email):
    """Grant a Google account edit access to a Drive file (best-effort)."""
    if not email or '@' not in str(email):
        return
    try:
        service.permissions().create(
            fileId=file_id,
            body={'type': 'user', 'role': 'writer', 'emailAddress': str(email).strip()},
            sendNotificationEmail=False,
            fields='id',
        ).execute()
    except Exception as err:
        print(f"[Drive] Could not grant editor to {email}: {err}")


def ensure_google_drive_main_folder_id(service, cursor, connection, existing_folder_id=None):
    """Return the firm main Drive folder id, creating and persisting it when missing."""
    folder_name = 'SHERIA CENTRIC'
    folder_id = existing_folder_id or session.get('google_drive_main_folder_id')
    if not folder_id:
        cursor.execute(
            "SELECT google_drive_main_folder_id FROM company_settings ORDER BY id DESC LIMIT 1"
        )
        row = cursor.fetchone()
        if row:
            folder_id = row.get('google_drive_main_folder_id') if isinstance(row, dict) else row[0]

    if folder_id:
        try:
            service.files().get(fileId=folder_id, fields='id').execute()
            session['google_drive_main_folder_id'] = folder_id
            return folder_id
        except HttpError:
            folder_id = None

    folder = service.files().create(
        body={'name': folder_name, 'mimeType': 'application/vnd.google-apps.folder'},
        fields='id',
    ).execute()
    folder_id = folder.get('id')
    cursor.execute(
        """
        UPDATE company_settings
        SET google_drive_main_folder_id = %s,
            updated_at = CURRENT_TIMESTAMP
        WHERE id = (SELECT id FROM (SELECT id FROM company_settings ORDER BY id DESC LIMIT 1) AS sub)
        """,
        (folder_id,),
    )
    connection.commit()
    session['google_drive_main_folder_id'] = folder_id
    return folder_id


def _sync_google_drive_session_from_settings_row(row):
    """Load Drive OAuth credentials from a company_settings row into the Flask session."""
    if not row or not row.get('google_drive_token') or not row.get('google_drive_refresh_token'):
        return False
    scopes = json.loads(row['google_drive_scopes']) if row.get('google_drive_scopes') else []
    session['google_drive_credentials'] = {
        'token': row['google_drive_token'],
        'refresh_token': row['google_drive_refresh_token'],
        'token_uri': row.get('google_drive_token_uri'),
        'client_id': GOOGLE_CLIENT_ID,
        'client_secret': GOOGLE_CLIENT_SECRET,
        'scopes': scopes,
    }
    if row.get('google_drive_account_email'):
        session['google_drive_account'] = {
            'email': row.get('google_drive_account_email'),
            'name': row.get('google_drive_account_name'),
            'picture': row.get('google_drive_account_picture'),
        }
    if row.get('google_drive_main_folder_id'):
        session['google_drive_main_folder_id'] = row['google_drive_main_folder_id']
    return True


@app.route('/api/case/<int:case_id>/upload-document', methods=['POST'])
def upload_case_document(case_id):
    """Upload a document for a specific case to Google Drive"""
    if 'employee_id' not in session:
        return jsonify({'success': False, 'error': 'Unauthorized'}), 401
    
    try:
        # Get Google Drive service
        service = get_google_drive_service()
        if not service:
            # Try loading from database
            connection = get_db_connection()
            if connection:
                try:
                    with connection.cursor(pymysql.cursors.DictCursor) as cursor:
                        cursor.execute("""
                            SELECT google_drive_token, google_drive_refresh_token, google_drive_token_uri,
                                   google_drive_scopes
                            FROM company_settings 
                            ORDER BY id DESC LIMIT 1
                        """)
                        settings = cursor.fetchone()
                        if settings and settings.get('google_drive_token') and settings.get('google_drive_refresh_token'):
                            scopes = json.loads(settings['google_drive_scopes']) if settings.get('google_drive_scopes') else []
                            session['google_drive_credentials'] = {
                                'token': settings['google_drive_token'],
                                'refresh_token': settings['google_drive_refresh_token'],
                                'token_uri': settings.get('google_drive_token_uri'),
                                'client_id': GOOGLE_CLIENT_ID,
                                'client_secret': GOOGLE_CLIENT_SECRET,
                                'scopes': scopes
                            }
                            service = get_google_drive_service()
                except Exception as e:
                    print(f"Error loading credentials: {e}")
                finally:
                    connection.close()
        
        if not service:
            print("ERROR: Google Drive service not available")
            return jsonify({'success': False, 'error': 'Google Drive not connected. Please connect Google Drive in Documents Settings.'}), 400
        
        # Get case and client information
        connection = get_db_connection()
        if not connection:
            return jsonify({'success': False, 'error': 'Database connection error'}), 500
        
        try:
            with connection.cursor(pymysql.cursors.DictCursor) as cursor:
                cursor.execute("""
                    SELECT 
                        c.id,
                        c.tracking_number,
                        c.client_id,
                        c.filled_by_id,
                        cl.id as client_table_id,
                        cl.full_name as client_full_name,
                        cl.phone_number as client_phone
                    FROM cases c
                    LEFT JOIN clients cl ON c.client_id = cl.id
                    WHERE c.id = %s
                """, (case_id,))
                case_data = cursor.fetchone()
                
                if not case_data:
                    return jsonify({'success': False, 'error': 'Case not found'}), 404
                
                if not case_data.get('client_table_id'):
                    return jsonify({'success': False, 'error': 'Client information not found for this case'}), 404

                employee_id = session.get('employee_id')
                user_role = session.get('employee_role')
                original_role = session.get('original_role')
                unrestricted = has_unrestricted_case_access(user_role, original_role)
                is_privileged_case_view_role = is_privileged_case_viewer(user_role)
                is_case_owner = str(case_data.get('filled_by_id') or '') == str(employee_id)
                task_id = (request.form.get('task_id') or request.args.get('task_id') or '').strip()
                if not unrestricted and not is_privileged_case_view_role and not is_case_owner:
                    ensure_task_management_table(cursor, connection)
                    if not has_active_case_task_access(cursor, case_id, employee_id, task_id or None, permission_key='upload_documents'):
                        return jsonify({'success': False, 'error': 'You can only upload while your allocated task is active.'}), 403

                # Get main folder ID
                main_folder_id = session.get('google_drive_main_folder_id')
                if not main_folder_id:
                    cursor.execute("""
                        SELECT google_drive_main_folder_id
                        FROM company_settings 
                        ORDER BY id DESC LIMIT 1
                    """)
                    settings = cursor.fetchone()
                    if settings and settings.get('google_drive_main_folder_id'):
                        main_folder_id = settings['google_drive_main_folder_id']
                        session['google_drive_main_folder_id'] = main_folder_id
                
                # If folder doesn't exist, create it automatically
                if not main_folder_id:
                    print("INFO: SHERIA CENTRIC folder not found, creating it automatically...")
                    try:
                        folder_name = 'SHERIA CENTRIC'
                        file_metadata = {
                            'name': folder_name,
                            'mimeType': 'application/vnd.google-apps.folder'
                        }
                        folder = service.files().create(
                            body=file_metadata,
                            fields='id, name, webViewLink'
                        ).execute()
                        
                        main_folder_id = folder.get('id')
                        session['google_drive_main_folder_id'] = main_folder_id
                        
                        # Save to database
                        cursor.execute("""
                            UPDATE company_settings 
                            SET google_drive_main_folder_id = %s,
                                updated_at = CURRENT_TIMESTAMP
                            WHERE id = (SELECT id FROM (SELECT id FROM company_settings ORDER BY id DESC LIMIT 1) AS sub)
                        """, (main_folder_id,))
                        connection.commit()
                        print(f"INFO: Created SHERIA CENTRIC folder with ID: {main_folder_id}")
                    except Exception as create_error:
                        print(f"ERROR: Failed to create SHERIA CENTRIC folder: {create_error}")
                        err_str = str(create_error).lower()
                        if 'invalid_grant' in err_str or 'expired' in err_str or 'revoked' in err_str:
                            return jsonify({
                                'success': False,
                                'error': 'Google Drive session expired or revoked. Please reconnect Google Drive in Documents Settings.',
                                'settings_url': url_for('documents_settings')
                            }), 400
                        return jsonify({
                            'success': False,
                            'error': f'Failed to create SHERIA CENTRIC folder: {str(create_error)}'
                        }), 500
                
                # Get or create client folder
                client_folder_name = get_user_folder_name(
                    case_data.get('client_phone'),
                    case_data.get('client_full_name'),
                    'client'
                )
                client_folder_id = get_or_create_folder(service, main_folder_id, client_folder_name)
                
                case_folder_name = get_case_drive_folder_name(case_data, case_id)
                case_doc_folder_id = get_or_create_folder(service, client_folder_id, case_folder_name)
                
                # Handle file upload
                print(f"DEBUG: request.files keys: {list(request.files.keys())}")
                print(f"DEBUG: request.form keys: {list(request.form.keys())}")
                
                if 'document_file' not in request.files:
                    print("ERROR: 'document_file' not in request.files")
                    return jsonify({'success': False, 'error': 'No file provided'}), 400
                
                file = request.files['document_file']
                print(f"DEBUG: file object: {file}, filename: {file.filename if file else 'None'}")
                
                if not file or file.filename == '':
                    print("ERROR: No file selected or empty filename")
                    return jsonify({'success': False, 'error': 'No file selected'}), 400
                
                # Validate file
                if not allowed_document_file(file.filename):
                    print(f"ERROR: Invalid file type: {file.filename}")
                    return jsonify({'success': False, 'error': 'Invalid file type. Allowed: PDF, DOC, DOCX, JPG, JPEG, PNG'}), 400
                
                # Read file content
                file_content = file.read()
                file_name = secure_filename(file.filename)
                description = request.form.get('description', '').strip()
                if not description:
                    return jsonify({'success': False, 'error': 'Description is required.'}), 400
                desc_words = description.split()
                if len(desc_words) > 5:
                    return jsonify({'success': False, 'error': 'Description must be 5 words or fewer.'}), 400

                # Optional: party this document is linked to (used for filtering by party type)
                party_id = (request.form.get('party_id') or '').strip()[:50]
                party_type = (request.form.get('party_type') or '').strip()
                party_name = (request.form.get('party_name') or '').strip()
                if party_type:
                    party_type = party_type.upper()[:100]
                party_name = party_name[:120]
                # If a party_id was supplied, verify it belongs to this case and resolve type/name
                # from the database to prevent client-side tampering of the link.
                if party_id:
                    try:
                        cursor.execute(
                            """
                            SELECT id, party_type, party_name
                            FROM case_parties
                            WHERE id = %s AND case_id = %s
                            LIMIT 1
                            """,
                            (party_id, case_id),
                        )
                        party_row = cursor.fetchone()
                        if party_row:
                            party_type = (party_row.get('party_type') or '').strip().upper()[:100]
                            party_name = (party_row.get('party_name') or '').strip()[:120]
                        else:
                            party_id = ''  # invalid for this case
                    except Exception as _party_lookup_err:
                        print(f"WARN: party lookup failed: {_party_lookup_err}")
                        party_id = ''

                # Determine MIME type
                file_ext = file_name.rsplit('.', 1)[1].lower() if '.' in file_name else ''
                mime_types = {
                    'pdf': 'application/pdf',
                    'doc': 'application/msword',
                    'docx': 'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
                    'jpg': 'image/jpeg',
                    'jpeg': 'image/jpeg',
                    'png': 'image/png'
                }
                mime_type = mime_types.get(file_ext, 'application/octet-stream')
                
                # Create file metadata
                file_properties = {
                    'uploaded_by_id': str(session.get('employee_id') or ''),
                    'uploaded_by_name': session.get('employee_name') or ''
                }
                if party_type:
                    file_properties['party_type'] = party_type
                if party_name:
                    file_properties['party_name'] = party_name
                if party_id:
                    file_properties['party_id'] = str(party_id)

                file_metadata = {
                    'name': file_name,
                    'parents': [case_doc_folder_id],
                    'properties': file_properties
                }
                file_metadata['description'] = description
                
                # Upload to Google Drive
                media = MediaIoBaseUpload(
                    BytesIO(file_content),
                    mimetype=mime_type,
                    resumable=True
                )
                
                uploaded_file = service.files().create(
                    body=file_metadata,
                    media_body=media,
                    fields='id, name, webViewLink, webContentLink'
                ).execute()
                
                file_id = uploaded_file.get('id')
                if not file_id:
                    return jsonify({
                        'success': False,
                        'error': 'Upload could not be verified. Please try again.'
                    }), 502
                try:
                    verified = service.files().get(fileId=file_id, fields='id').execute()
                    if not verified or not verified.get('id'):
                        return jsonify({
                            'success': False,
                            'error': 'Upload verification failed. Please try again.'
                        }), 502
                except Exception as verify_error:
                    print(f"Upload verification failed for file {file_id}: {verify_error}")
                    return jsonify({
                        'success': False,
                        'error': 'Upload verification failed. Please try again.'
                    }), 502
                file_url = uploaded_file.get('webViewLink', f"https://drive.google.com/file/d/{file_id}/view")
                
                return jsonify({
                    'success': True,
                    'message': 'Document uploaded successfully',
                    'file_id': file_id,
                    'file_name': file_name,
                    'file_url': file_url
                })
        finally:
            connection.close()
            
    except HttpError as error:
        print(f"Google Drive API error: {error}")
        error_details = error.error_details[0] if error.error_details else {}
        error_reason = error_details.get('reason', str(error))
        return jsonify({
            'success': False,
            'error': f'Google Drive API error: {error_reason}'
        }), 500
    except Exception as e:
        print(f"Error uploading document: {e}")
        import traceback
        traceback.print_exc()
        error_message = str(e).lower()
        # Token expired/revoked: tell user to reconnect Google Drive
        if 'invalid_grant' in error_message or 'token' in error_message and ('expired' in error_message or 'revoked' in error_message):
            return jsonify({
                'success': False,
                'error': 'Google Drive session expired or revoked. Please reconnect Google Drive in Documents Settings.',
                'settings_url': url_for('documents_settings')
            }), 400
        # Other client-friendly errors
        status_code = 500
        if 'not found' in error_message or 'not connected' in error_message:
            status_code = 400
        return jsonify({
            'success': False,
            'error': f'Upload failed: {str(e)}'
        }), status_code

@app.route('/api/case/<int:case_id>/drive-folder')
def get_case_drive_folder(case_id):
    """Get or create the case folder in Google Drive and return its URL. No document creation."""
    if 'employee_id' not in session:
        return jsonify({'success': False, 'error': 'Unauthorized'}), 401
    service = get_google_drive_service()
    if not service:
        connection = get_db_connection()
        if connection:
            try:
                with connection.cursor(pymysql.cursors.DictCursor) as cursor:
                    cursor.execute("""
                        SELECT google_drive_token, google_drive_refresh_token, google_drive_token_uri, google_drive_scopes
                        FROM company_settings ORDER BY id DESC LIMIT 1
                    """)
                    row = cursor.fetchone()
                    if row and row.get('google_drive_token') and row.get('google_drive_refresh_token'):
                        scopes = json.loads(row['google_drive_scopes']) if row.get('google_drive_scopes') else []
                        session['google_drive_credentials'] = {
                            'token': row['google_drive_token'],
                            'refresh_token': row['google_drive_refresh_token'],
                            'token_uri': row.get('google_drive_token_uri'),
                            'client_id': GOOGLE_CLIENT_ID,
                            'client_secret': GOOGLE_CLIENT_SECRET,
                            'scopes': scopes
                        }
                        service = get_google_drive_service()
            except Exception as e:
                print(f"Error loading credentials: {e}")
            finally:
                connection.close()
    if not service:
        return jsonify({'success': False, 'error': 'Google Drive not connected. Connect in Documents Settings.'}), 400
    connection = get_db_connection()
    if not connection:
        return jsonify({'success': False, 'error': 'Database connection error'}), 500
    try:
        with connection.cursor(pymysql.cursors.DictCursor) as cursor:
            cursor.execute("""
                SELECT c.id, c.tracking_number, c.client_id,
                       cl.id as client_table_id, cl.full_name as client_full_name, cl.phone_number as client_phone
                FROM cases c
                LEFT JOIN clients cl ON c.client_id = cl.id
                WHERE c.id = %s
            """, (case_id,))
            case_data = cursor.fetchone()
            if not case_data:
                return jsonify({'success': False, 'error': 'Case not found'}), 404
            if not case_data.get('client_table_id'):
                return jsonify({'success': False, 'error': 'Client not found for this case'}), 404
            main_folder_id = session.get('google_drive_main_folder_id')
            if not main_folder_id:
                cursor.execute("SELECT google_drive_main_folder_id FROM company_settings ORDER BY id DESC LIMIT 1")
                row = cursor.fetchone()
                if row and row.get('google_drive_main_folder_id'):
                    main_folder_id = row['google_drive_main_folder_id']
                    session['google_drive_main_folder_id'] = main_folder_id
            if not main_folder_id:
                return jsonify({'success': False, 'error': 'Google Drive main folder not configured'}), 400
            client_folder_name = get_user_folder_name(
                case_data.get('client_phone'),
                case_data.get('client_full_name'),
                'client'
            )
            client_folder_id = get_or_create_folder(service, main_folder_id, client_folder_name)
            case_folder_name = get_case_drive_folder_name(case_data, case_id)
            case_doc_folder_id = get_or_create_folder(service, client_folder_id, case_folder_name)
            folder_url = f'https://drive.google.com/drive/folders/{case_doc_folder_id}'
            return jsonify({
                'success': True,
                'folder_id': case_doc_folder_id,
                'folder_url': folder_url,
                'folder_name': case_folder_name
            })
    except Exception as e:
        print(f"Error getting case drive folder: {e}")
        return jsonify({'success': False, 'error': str(e)}), 500
    finally:
        connection.close()

@app.route('/api/case/<int:case_id>/create-google-file', methods=['POST'])
def create_case_google_file(case_id):
    """Create a new Google Doc, Sheet, or Slides in the case's Drive folder and return the edit link."""
    if 'employee_id' not in session:
        return jsonify({'success': False, 'error': 'Unauthorized'}), 401
    try:
        data = request.get_json() or {}
        file_type = (data.get('type') or '').strip().lower()
        file_name = (data.get('name') or '').strip()
        task_id = str(data.get('task_id') or '').strip()
        party_id_in = str(data.get('party_id') or '').strip()[:50]
        party_type_in = (data.get('party_type') or '').strip()
        party_name_in = (data.get('party_name') or '').strip()
        description_in = (data.get('description') or '').strip()
        if file_type not in ('doc', 'sheet', 'slides', 'notebook'):
            return jsonify({'success': False, 'error': 'Invalid type. Use doc, sheet, slides, or notebook.'}), 400
        if description_in:
            desc_words = description_in.split()
            if len(desc_words) > 5:
                return jsonify({'success': False, 'error': 'Description must be 5 words or fewer.'}), 400
        connection = get_db_connection()
        if not connection:
            return jsonify({'success': False, 'error': 'Database connection error'}), 500
        try:
            with connection.cursor(pymysql.cursors.DictCursor) as cursor:
                cursor.execute("""
                    SELECT google_drive_token, google_drive_refresh_token, google_drive_token_uri,
                           google_drive_scopes, google_drive_main_folder_id
                    FROM company_settings ORDER BY id DESC LIMIT 1
                """)
                drive_settings = cursor.fetchone()
                if not drive_settings or not drive_settings.get('google_drive_token') or not drive_settings.get('google_drive_refresh_token'):
                    return jsonify({'success': False, 'error': 'Google Drive not connected. Connect in Documents Settings.'}), 400

                drive_scopes = json.loads(drive_settings['google_drive_scopes']) if drive_settings.get('google_drive_scopes') else []
                company_creds_dict = {
                    'token': drive_settings['google_drive_token'],
                    'refresh_token': drive_settings['google_drive_refresh_token'],
                    'token_uri': drive_settings.get('google_drive_token_uri'),
                    'client_id': GOOGLE_CLIENT_ID,
                    'client_secret': GOOGLE_CLIENT_SECRET,
                    'scopes': drive_scopes
                }

                credentials = Credentials(
                    token=company_creds_dict.get('token'),
                    refresh_token=company_creds_dict.get('refresh_token'),
                    token_uri=company_creds_dict.get('token_uri'),
                    client_id=company_creds_dict.get('client_id'),
                    client_secret=company_creds_dict.get('client_secret'),
                    scopes=company_creds_dict.get('scopes')
                )
                ok, _info = refresh_drive_credentials_safely(credentials, cursor, connection)
                if not ok:
                    raise RefreshError('invalid_grant: Google Drive needs reconnect')
                company_creds_dict['token'] = credentials.token

                service = build('drive', 'v3', credentials=credentials)

                cursor.execute("""
                    SELECT c.id, c.tracking_number, c.client_id, c.filled_by_id,
                           cl.id as client_table_id, cl.full_name as client_full_name, cl.phone_number as client_phone
                    FROM cases c
                    LEFT JOIN clients cl ON c.client_id = cl.id
                    WHERE c.id = %s
                """, (case_id,))
                case_data = cursor.fetchone()
                if not case_data:
                    return jsonify({'success': False, 'error': 'Case not found'}), 404
                if not case_data.get('client_table_id'):
                    return jsonify({'success': False, 'error': 'Client not found for this case'}), 404

                employee_id = session.get('employee_id')
                user_role = session.get('employee_role')
                original_role = session.get('original_role')
                unrestricted = has_unrestricted_case_access(user_role, original_role)
                is_privileged_case_view_role = is_privileged_case_viewer(user_role)
                is_case_owner = str(case_data.get('filled_by_id') or '') == str(employee_id)
                if not unrestricted and not is_privileged_case_view_role and not is_case_owner:
                    ensure_task_management_table(cursor, connection)
                    if not task_id:
                        return jsonify({'success': False, 'error': 'task_id is required for task-based case access.'}), 403
                    if not has_active_case_task_access(cursor, case_id, employee_id, task_id, permission_key='upload_documents'):
                        return jsonify({'success': False, 'error': 'You can only create files while your allocated task is active.'}), 403
                main_folder_id = drive_settings.get('google_drive_main_folder_id')
                if not main_folder_id:
                    return jsonify({'success': False, 'error': 'Google Drive main folder not configured'}), 400
                branding_assets_folder_id = get_or_create_folder(
                    service, main_folder_id, '_Branding image cache'
                )
                client_folder_name = get_user_folder_name(
                    case_data.get('client_phone'),
                    case_data.get('client_full_name'),
                    'client'
                )
                client_folder_id = get_or_create_folder(service, main_folder_id, client_folder_name)
                case_folder_name = get_case_drive_folder_name(case_data, case_id)
                case_doc_folder_id = get_or_create_folder(service, client_folder_id, case_folder_name)
                tracking = (case_data.get('tracking_number') or '').strip() or f'Case-{case_id}'
                tracking = re.sub(r'[\\/:*?"<>|]', '_', tracking)
                company_settings = get_company_settings()
                company_name = (company_settings.get('company_name') or 'Company').strip() if company_settings else 'Company'
                employee_name = session.get('employee_name') or ''
                if not employee_name and session.get('employee_id'):
                    cursor.execute("SELECT full_name FROM employees WHERE id = %s", (session['employee_id'],))
                    emp_row = cursor.fetchone()
                    employee_name = (emp_row.get('full_name') or '').strip() if emp_row else ''
                # Document title: user's name - document follow-up number (case tracking)
                auto_title = f"{employee_name or 'Document'} - {tracking}"
                mime_and_default = {
                    'doc': ('application/vnd.google-apps.document', auto_title),
                    'sheet': ('application/vnd.google-apps.spreadsheet', auto_title),
                    'slides': ('application/vnd.google-apps.presentation', auto_title),
                    'notebook': ('application/vnd.google-apps.document', f"{auto_title} - NOTEBOOK"),
                }
                mime_type, default_name = mime_and_default[file_type]
                name = file_name if file_name else default_name

                # Resolve / validate the optional linked party so it can't be tampered with
                resolved_party_id = ''
                resolved_party_type = (party_type_in or '').upper()[:100]
                resolved_party_name = (party_name_in or '')[:120]
                if party_id_in:
                    try:
                        cursor.execute(
                            """
                            SELECT id, party_type, party_name
                            FROM case_parties
                            WHERE id = %s AND case_id = %s
                            LIMIT 1
                            """,
                            (party_id_in, case_id),
                        )
                        party_row = cursor.fetchone()
                        if party_row:
                            resolved_party_id = str(party_row['id'])
                            resolved_party_type = (party_row.get('party_type') or '').strip().upper()[:100]
                            resolved_party_name = (party_row.get('party_name') or '').strip()[:120]
                        else:
                            # Invalid id for this case — drop the link rather than store something wrong
                            resolved_party_type = ''
                            resolved_party_name = ''
                    except Exception as _party_lookup_err:
                        print(f"WARN: party lookup failed (create google file): {_party_lookup_err}")
                        resolved_party_type = ''
                        resolved_party_name = ''

                file_properties = {
                    'created_by_id': str(session.get('employee_id') or ''),
                    'created_by_name': session.get('employee_name') or '',
                    'uploaded_by_id': str(session.get('employee_id') or ''),
                    'uploaded_by_name': session.get('employee_name') or '',
                    'task_id': task_id,
                    'task_type': 'case'
                }
                if resolved_party_id:
                    file_properties['party_id'] = resolved_party_id
                if resolved_party_type:
                    file_properties['party_type'] = resolved_party_type
                if resolved_party_name:
                    file_properties['party_name'] = resolved_party_name

                file_metadata = {
                    'name': name,
                    'mimeType': mime_type,
                    'parents': [case_doc_folder_id],
                    'properties': file_properties
                }
                if description_in:
                    file_metadata['description'] = description_in
                created = service.files().create(
                    body=file_metadata,
                    fields='id, name, webViewLink'
                ).execute()
                file_id = created.get('id')
                # Make file directly accessible via link to avoid access-request prompts.
                try:
                    service.permissions().create(
                        fileId=file_id,
                        body={'type': 'anyone', 'role': 'reader'},
                        fields='id'
                    ).execute()
                except Exception as perm_err:
                    print(f"Warning setting case file public permission: {perm_err}")
                docs_message = None
                docs_content_added = False
                DOCS_SCOPE = 'https://www.googleapis.com/auth/documents'
                # For Google Docs / Notes: insert company header, footer, letterhead, and logo
                if file_type in ('doc', 'notebook') and company_settings:
                    creds_dict = company_creds_dict
                    stored_scopes = (creds_dict or {}).get('scopes') or []
                    has_docs_scope = any(
                        'auth/documents' in (scope or '') for scope in stored_scopes
                    )
                    if creds_dict and not has_docs_scope:
                        docs_message = (
                            'Reconnect Google Drive in Documents Settings to add letterhead, '
                            'footer, stamp, and signature to new documents.'
                        )
                    elif creds_dict:
                        try:
                            credentials = Credentials(
                                token=creds_dict.get('token'),
                                refresh_token=creds_dict.get('refresh_token'),
                                token_uri=creds_dict.get('token_uri'),
                                client_id=creds_dict.get('client_id'),
                                client_secret=creds_dict.get('client_secret'),
                                scopes=creds_dict.get('scopes')
                            )
                            docs_service = build('docs', 'v1', credentials=credentials)
                            emp_signature = None
                            emp_stamp = None
                            emp_id = session.get('employee_id')
                            if emp_id:
                                cursor.execute(
                                    "SELECT signature, stamp FROM employees WHERE id = %s",
                                    (emp_id,),
                                )
                                emp_row = cursor.fetchone() or {}
                                emp_signature = emp_row.get('signature')
                                emp_stamp = emp_row.get('stamp')
                            docs_content_added, branding_warning = apply_google_doc_company_branding(
                                docs_service,
                                file_id,
                                company_settings,
                                company_name,
                                employee_name,
                                employee_signature_file=emp_signature,
                                employee_stamp_file=emp_stamp,
                                drive_service=service,
                                drive_assets_folder_id=branding_assets_folder_id,
                            )
                            if branding_warning and not docs_message:
                                docs_message = branding_warning
                        except HttpError as docs_err:
                            err_msg = str(docs_err).lower()
                            if '403' in err_msg or 'insufficient' in err_msg or 'scope' in err_msg or 'permission' in err_msg:
                                docs_message = (
                            'Reconnect Google Drive in Documents Settings to add letterhead, '
                            'footer, stamp, and signature to new documents.'
                        )
                            else:
                                docs_message = _google_docs_api_error_message(docs_err, app_label='document')
                            print(f"Docs API insert failed: {docs_err}")
                        except Exception as docs_err:
                            print(f"Docs API insert failed: {docs_err}")
                edit_urls = {
                    'doc': f'https://docs.google.com/document/d/{file_id}/edit',
                    'sheet': f'https://docs.google.com/spreadsheets/d/{file_id}/edit',
                    'slides': f'https://docs.google.com/presentation/d/{file_id}/edit',
                    'notebook': f'https://docs.google.com/document/d/{file_id}/edit',
                }
                payload = {
                    'success': True,
                    'file_id': file_id,
                    'name': created.get('name', name),
                    'webViewLink': created.get('webViewLink') or f'https://drive.google.com/file/d/{file_id}/view',
                    'editLink': edit_urls.get(file_type)
                }
                if docs_message:
                    payload['docs_message'] = docs_message
                    payload['docs_settings_url'] = url_for('documents_settings')
                if file_type in ('doc', 'notebook'):
                    payload['docs_content_added'] = docs_content_added
                return jsonify(payload)
        except Exception as e:
            err_str = str(e).lower()
            if 'invalid_grant' in err_str or 'expired' in err_str or 'revoked' in err_str:
                return jsonify({
                    'success': False,
                    'error': 'Google Drive session expired or revoked. Please reconnect in Documents Settings.',
                    'settings_url': url_for('documents_settings')
                }), 400
            raise
        finally:
            connection.close()
    except Exception as e:
        print(f"Create case google file error: {e}")
        return jsonify({'success': False, 'error': str(e)}), 500

@app.route('/api/matter/<int:matter_id>/create-google-file', methods=['POST'])
def create_matter_google_file(matter_id):
    """Create a Google Doc/Sheet/Slides/Notebook in the matter's Drive folder."""
    if 'employee_id' not in session:
        return jsonify({'success': False, 'error': 'Unauthorized'}), 401
    try:
        data = request.get_json() or {}
        file_type = (data.get('type') or '').strip().lower()
        file_name = (data.get('name') or '').strip()
        task_id = str(data.get('task_id') or '').strip()
        if file_type not in ('doc', 'sheet', 'slides', 'notebook'):
            return jsonify({'success': False, 'error': 'Invalid type. Use doc, sheet, slides, or notebook.'}), 400

        connection = get_db_connection()
        if not connection:
            return jsonify({'success': False, 'error': 'Database connection error'}), 500
        try:
            with connection.cursor(pymysql.cursors.DictCursor) as cursor:
                cursor.execute("""
                    SELECT google_drive_token, google_drive_refresh_token, google_drive_token_uri,
                           google_drive_scopes, google_drive_main_folder_id
                    FROM company_settings ORDER BY id DESC LIMIT 1
                """)
                drive_settings = cursor.fetchone()
                if not drive_settings or not drive_settings.get('google_drive_token') or not drive_settings.get('google_drive_refresh_token'):
                    return jsonify({'success': False, 'error': 'Google Drive not connected. Connect in Documents Settings.'}), 400

                drive_scopes = json.loads(drive_settings['google_drive_scopes']) if drive_settings.get('google_drive_scopes') else []
                credentials = Credentials(
                    token=drive_settings.get('google_drive_token'),
                    refresh_token=drive_settings.get('google_drive_refresh_token'),
                    token_uri=drive_settings.get('google_drive_token_uri'),
                    client_id=GOOGLE_CLIENT_ID,
                    client_secret=GOOGLE_CLIENT_SECRET,
                    scopes=drive_scopes
                )
                ok, _info = refresh_drive_credentials_safely(credentials, cursor, connection)
                if not ok:
                    raise RefreshError('invalid_grant: Google Drive needs reconnect')

                cursor.execute("""
                    SELECT
                        m.id, m.matter_reference_number, m.matter_title, m.client_id, m.client_name, m.client_phone, m.assigned_employee_id,
                        cl.full_name AS client_full_name, cl.phone_number AS client_phone_number
                    FROM matters m
                    LEFT JOIN clients cl ON m.client_id = cl.id
                    WHERE m.id = %s
                """, (matter_id,))
                matter_data = cursor.fetchone()
                if not matter_data:
                    return jsonify({'success': False, 'error': 'Matter not found'}), 404

                current_employee_id = session.get('employee_id')
                if str(matter_data.get('assigned_employee_id') or '') != str(current_employee_id):
                    user_role = session.get('employee_role')
                    original_role = session.get('original_role')
                    if user_role != 'IT Support' and original_role != 'IT Support':
                        return jsonify({'success': False, 'error': 'You do not have access to this matter'}), 403

                main_folder_id = drive_settings.get('google_drive_main_folder_id')
                if not main_folder_id:
                    return jsonify({'success': False, 'error': 'Google Drive main folder not configured'}), 400

                service = build('drive', 'v3', credentials=credentials)
                branding_assets_folder_id = get_or_create_folder(
                    service, main_folder_id, '_Branding image cache'
                )
                client_phone = matter_data.get('client_phone_number') or matter_data.get('client_phone')
                client_name = matter_data.get('client_full_name') or matter_data.get('client_name') or ''
                if client_name or client_phone:
                    client_folder_name = get_user_folder_name(client_phone, client_name, 'client')
                    client_folder_id = get_or_create_folder(service, main_folder_id, client_folder_name)
                else:
                    client_folder_id = get_or_create_folder(service, main_folder_id, 'Non-Litigation Matters')

                ref = (matter_data.get('matter_reference_number') or '').strip() or f'Matter-{matter_id}'
                ref_safe = re.sub(r'[\\/:*?"<>|]', '_', ref)
                matter_folder_name = f"Matter {ref_safe}"
                matter_doc_folder_id = get_or_create_folder(service, client_folder_id, matter_folder_name)

                employee_name = (session.get('employee_name') or '').strip() or 'Document'
                auto_title = f"{employee_name} - {ref_safe}"
                mime_and_default = {
                    'doc': ('application/vnd.google-apps.document', auto_title),
                    'sheet': ('application/vnd.google-apps.spreadsheet', auto_title),
                    'slides': ('application/vnd.google-apps.presentation', auto_title),
                    'notebook': ('application/vnd.google-apps.document', f"{auto_title} - NOTEBOOK"),
                }
                mime_type, default_name = mime_and_default[file_type]
                name = file_name if file_name else default_name

                created = service.files().create(
                    body={
                        'name': name,
                        'mimeType': mime_type,
                        'parents': [matter_doc_folder_id],
                        'properties': {
                            'created_by_id': str(session.get('employee_id') or ''),
                            'created_by_name': session.get('employee_name') or '',
                            'task_id': task_id,
                            'task_type': 'matter'
                        }
                    },
                    fields='id, name, webViewLink'
                ).execute()
                file_id = created.get('id')
                # Make file directly accessible via link to avoid access-request prompts.
                try:
                    service.permissions().create(
                        fileId=file_id,
                        body={'type': 'anyone', 'role': 'reader'},
                        fields='id'
                    ).execute()
                except Exception as perm_err:
                    print(f"Warning setting matter file public permission: {perm_err}")
                docs_message = None
                docs_content_added = False
                company_settings = get_company_settings()
                DOCS_SCOPE = 'https://www.googleapis.com/auth/documents'
                if file_type in ('doc', 'notebook') and company_settings:
                    has_docs_scope = any(
                        'auth/documents' in (scope or '') for scope in drive_scopes
                    )
                    if not has_docs_scope:
                        docs_message = (
                            'Reconnect Google Drive in Documents Settings to add letterhead, '
                            'footer, stamp, and signature to new documents.'
                        )
                    else:
                        try:
                            docs_service = build('docs', 'v1', credentials=credentials)
                            company_name = (company_settings.get('company_name') or '').strip() or 'Law Firm'
                            emp_signature = None
                            emp_stamp = None
                            emp_id = session.get('employee_id')
                            if emp_id:
                                cursor.execute(
                                    "SELECT signature, stamp FROM employees WHERE id = %s",
                                    (emp_id,),
                                )
                                emp_row = cursor.fetchone() or {}
                                emp_signature = emp_row.get('signature')
                                emp_stamp = emp_row.get('stamp')
                            docs_content_added, branding_warning = apply_google_doc_company_branding(
                                docs_service,
                                file_id,
                                company_settings,
                                company_name,
                                employee_name,
                                employee_signature_file=emp_signature,
                                employee_stamp_file=emp_stamp,
                                drive_service=service,
                                drive_assets_folder_id=branding_assets_folder_id,
                            )
                            if branding_warning and not docs_message:
                                docs_message = branding_warning
                        except HttpError as docs_err:
                            err_msg = str(docs_err).lower()
                            if '403' in err_msg or 'insufficient' in err_msg or 'scope' in err_msg:
                                docs_message = (
                                    'Reconnect Google Drive in Documents Settings to add letterhead, '
                                    'footer, stamp, and signature to new documents.'
                                )
                            else:
                                docs_message = _google_docs_api_error_message(docs_err, app_label='document')
                            print(f"Matter Docs API insert failed: {docs_err}")
                        except Exception as docs_err:
                            print(f"Matter Docs API insert failed: {docs_err}")
                edit_urls = {
                    'doc': f'https://docs.google.com/document/d/{file_id}/edit',
                    'sheet': f'https://docs.google.com/spreadsheets/d/{file_id}/edit',
                    'slides': f'https://docs.google.com/presentation/d/{file_id}/edit',
                    'notebook': f'https://docs.google.com/document/d/{file_id}/edit',
                }
                payload = {
                    'success': True,
                    'file_id': file_id,
                    'name': created.get('name', name),
                    'webViewLink': created.get('webViewLink') or f'https://drive.google.com/file/d/{file_id}/view',
                    'editLink': edit_urls.get(file_type),
                }
                if docs_message:
                    payload['docs_message'] = docs_message
                    payload['docs_settings_url'] = url_for('system_settings_section', section='documents')
                if file_type in ('doc', 'notebook'):
                    payload['docs_content_added'] = docs_content_added
                return jsonify(payload)
        finally:
            connection.close()
    except Exception as e:
        print(f"Create matter google file error: {e}")
        return jsonify({'success': False, 'error': str(e)}), 500

@app.route('/api/case/<int:case_id>/document/action/send-code', methods=['POST'])
def case_document_send_code(case_id):
    """Send a verification code before downloading or deleting a case document."""
    if 'employee_id' not in session:
        return jsonify({'success': False, 'error': 'Unauthorized'}), 401

    _ensure_document_action_verifications_table()
    data = request.get_json(silent=True) or request.form
    payload, err = _parse_drive_document_action_payload(data)
    if err:
        return jsonify({'success': False, 'error': err}), 400

    task_id = (data.get('task_id') or request.args.get('task_id') or '').strip() or None
    connection = get_db_connection()
    if not connection:
        return jsonify({'success': False, 'error': 'Database connection error'}), 500

    try:
        from datetime import datetime as _dt, timedelta as _td
        with connection.cursor(pymysql.cursors.DictCursor) as cursor:
            allowed, deny_msg = _case_document_action_allowed(
                cursor, case_id, session['employee_id'], task_id,
                permission_key='download' if payload['action'] == 'download' else 'view',
            )
            if not allowed:
                return jsonify({'success': False, 'error': deny_msg}), 403

            employee, emp_err = _send_employee_document_action_code(session['employee_id'])
            if emp_err:
                return jsonify({'success': False, 'error': emp_err}), 400
            delivery_email = (employee.get('personal_email') or employee.get('work_email') or '').strip()

            cursor.execute("""
                UPDATE document_action_verifications SET used = 1
                WHERE employee_id = %s AND case_id = %s AND used = 0
            """, (session['employee_id'], case_id))

            code = f"{secrets.randbelow(1_000_000):06d}"
            code_hash = generate_password_hash(code)
            expires_at = _dt.utcnow() + _td(minutes=10)
            cursor.execute("""
                INSERT INTO document_action_verifications
                    (employee_id, case_id, action, doc_kind, drive_file_id, code_hash, expires_at)
                VALUES (%s, %s, %s, %s, %s, %s, %s)
            """, (
                session['employee_id'], case_id,
                payload['action'], payload['doc_kind'],
                payload['drive_file_id'], code_hash, expires_at,
            ))
            connection.commit()

        action_label = 'Download document' if payload['action'] == 'download' else 'Delete document'
        sent = _send_document_action_code_email(delivery_email, code, employee.get('full_name'), action_label)
        if not sent:
            return jsonify({'success': False, 'error': 'Could not send verification email. Try again later.'}), 500

        return jsonify({
            'success': True,
            'message': f'A verification code has been sent to {_mask_email_address(delivery_email)}.',
            'delivery_email': _mask_email_address(delivery_email),
            'expires_in_minutes': 10,
        })
    except Exception as e:
        print(f"[case_document_send_code] error: {e}")
        return jsonify({'success': False, 'error': 'Something went wrong. Please try again.'}), 500
    finally:
        connection.close()


@app.route('/api/case/<int:case_id>/document/action/verify-code', methods=['POST'])
def case_document_verify_code(case_id):
    """Verify the emailed code and return a short-lived one-time action token."""
    if 'employee_id' not in session:
        return jsonify({'success': False, 'error': 'Unauthorized'}), 401

    _ensure_document_action_verifications_table()
    data = request.get_json(silent=True) or request.form
    payload, err = _parse_drive_document_action_payload(data)
    if err:
        return jsonify({'success': False, 'error': err}), 400

    code = (data.get('code') or '').strip()
    if not code.isdigit() or len(code) != 6:
        return jsonify({'success': False, 'error': 'Code must be 6 digits.'}), 400

    task_id = (data.get('task_id') or '').strip() or None
    connection = get_db_connection()
    if not connection:
        return jsonify({'success': False, 'error': 'Database connection error'}), 500

    try:
        from datetime import datetime as _dt, timedelta as _td
        with connection.cursor(pymysql.cursors.DictCursor) as cursor:
            allowed, deny_msg = _case_document_action_allowed(
                cursor, case_id, session['employee_id'], task_id,
                permission_key='download' if payload['action'] == 'download' else 'view',
            )
            if not allowed:
                return jsonify({'success': False, 'error': deny_msg}), 403

            cursor.execute("""
                SELECT id, code_hash, expires_at, used
                FROM document_action_verifications
                WHERE employee_id = %s AND case_id = %s
                  AND action = %s AND doc_kind = %s
                  AND (drive_file_id <=> %s)
                  AND used = 0
                ORDER BY id DESC
                LIMIT 1
            """, (
                session['employee_id'], case_id,
                payload['action'], payload['doc_kind'],
                payload['drive_file_id'],
            ))
            row = cursor.fetchone()
            if not row:
                return jsonify({'success': False, 'error': 'Invalid or expired code. Request a new one.'}), 400
            if row.get('expires_at') and row['expires_at'] < _dt.utcnow():
                return jsonify({'success': False, 'error': 'Code expired. Please request a new one.'}), 400
            if not check_password_hash(row['code_hash'], code):
                return jsonify({'success': False, 'error': 'Incorrect verification code.'}), 400

            action_token = secrets.token_urlsafe(32)
            token_hash = generate_password_hash(action_token)
            verified_at = _dt.utcnow()
            token_expires_at = verified_at + _td(minutes=5)
            cursor.execute("""
                UPDATE document_action_verifications
                SET verified_at = %s, action_token_hash = %s, token_expires_at = %s
                WHERE id = %s
            """, (verified_at, token_hash, token_expires_at, row['id']))
            connection.commit()

        return jsonify({
            'success': True,
            'message': 'Code verified.',
            'action_token': action_token,
            'expires_in_minutes': 5,
        })
    except Exception as e:
        print(f"[case_document_verify_code] error: {e}")
        return jsonify({'success': False, 'error': 'Something went wrong. Please try again.'}), 500
    finally:
        connection.close()


