@app.route('/case_management/<int:case_id>/document/<file_id>/download')
def download_case_document(case_id, file_id):
    """Stream a case document from Google Drive as a download (attachment)."""
    if 'employee_id' not in session:
        return redirect(url_for('login'))
    user_role = session.get('employee_role')
    original_role = session.get('original_role')
    allowed_roles = ['IT Support', 'Firm Administrator', 'Managing Partner', 'Clerk', 'Associate Advocate']
    if (user_role not in allowed_roles) and (original_role != 'IT Support'):
        flash('You do not have permission to download this document.', 'error')
        return redirect(url_for('case_management'))
    token = (request.args.get('token') or '').strip()
    if not token:
        flash('Email verification is required before downloading. Please verify from the case page.', 'error')
        redirect_kw = {'case_id': case_id}
        _task_id = (request.args.get('task_id') or '').strip()
        if _task_id:
            redirect_kw['task_id'] = _task_id
        return redirect(url_for('case_details', **redirect_kw))
    connection = get_db_connection()
    if not connection:
        return redirect(url_for('case_documents', case_id=case_id))
    task_id = (request.args.get('task_id') or '').strip()
    try:
        with connection.cursor(pymysql.cursors.DictCursor) as cursor:
            allowed, deny_msg = _case_document_action_allowed(
                cursor, case_id, session['employee_id'], task_id or None, permission_key='download',
            )
            if not allowed:
                flash(deny_msg or 'Permission denied.', 'error')
                return redirect(url_for('my_tasks') if 'task' in (deny_msg or '').lower() else url_for('case_management'))
            _ensure_document_action_verifications_table()
            payload = {
                'action': 'download',
                'doc_kind': 'drive',
                'drive_file_id': file_id,
            }
            if not _consume_case_document_action_token(cursor, session['employee_id'], case_id, payload, token):
                flash('Verification expired or invalid. Please try again.', 'error')
                redirect_kw = {'case_id': case_id}
                if task_id:
                    redirect_kw['task_id'] = task_id
                return redirect(url_for('case_details', **redirect_kw))
            connection.commit()
    finally:
        connection.close()
    service = get_google_drive_service()
    if not service:
        flash('Google Drive is not connected.', 'error')
        return redirect(url_for('case_documents', case_id=case_id))
    try:
        meta = service.files().get(fileId=file_id, fields='name,mimeType').execute()
        name = meta.get('name', 'document')
        mime = meta.get('mimeType', '')
        if mime and mime.startswith('application/vnd.google-apps.'):
            export_map = {
                'application/vnd.google-apps.document': ('application/pdf', '.pdf'),
                'application/vnd.google-apps.spreadsheet': ('application/vnd.openxmlformats-officedocument.spreadsheetml.sheet', '.xlsx'),
                'application/vnd.google-apps.presentation': ('application/pdf', '.pdf'),
            }
            exp_mime, ext = export_map.get(mime, ('application/pdf', '.pdf'))
            content = service.files().export(fileId=file_id, mimeType=exp_mime).execute()
            base_name = name.rsplit('.', 1)[0] if '.' in name else name
            download_name = base_name + ext
            return send_file(BytesIO(content), as_attachment=True, download_name=download_name, mimetype=exp_mime)
        request_dl = service.files().get_media(fileId=file_id)
        buf = BytesIO()
        downloader = MediaIoBaseDownload(buf, request_dl)
        done = False
        while not done:
            _, done = downloader.next_chunk()
        buf.seek(0)
        return send_file(buf, as_attachment=True, download_name=name, mimetype=mime or 'application/octet-stream')
    except HttpError as e:
        print(f"Drive download error: {e}")
        flash('Could not download file from Google Drive.', 'error')
        return redirect(url_for('case_documents', case_id=case_id))
    except Exception as e:
        print(f"Download error: {e}")
        flash('Download failed.', 'error')
        return redirect(url_for('case_documents', case_id=case_id))

@app.route('/api/case/<int:case_id>/document/<file_id>/delete', methods=['POST', 'DELETE'])
def delete_case_document_api(case_id, file_id):
    """Delete a case document from Google Drive. File must be in the case's folder."""
    if 'employee_id' not in session:
        return jsonify({'success': False, 'error': 'Unauthorized'}), 401
    user_role = session.get('employee_role')
    original_role = session.get('original_role')
    allowed_roles = ['IT Support', 'Firm Administrator', 'Managing Partner', 'Clerk', 'Associate Advocate']
    if (user_role not in allowed_roles) and (original_role != 'IT Support'):
        return jsonify({'success': False, 'error': 'Permission denied'}), 403
    data = request.get_json(silent=True) or request.form
    token = (data.get('token') or request.args.get('token') or '').strip()
    if not token:
        return jsonify({'success': False, 'error': 'Email verification is required before deleting.'}), 403
    connection = get_db_connection()
    if not connection:
        return jsonify({'success': False, 'error': 'Database error'}), 500
    try:
        with connection.cursor(pymysql.cursors.DictCursor) as cursor:
            task_id = (data.get('task_id') or request.args.get('task_id') or '').strip()
            allowed, deny_msg = _case_document_action_allowed(
                cursor, case_id, session['employee_id'], task_id or None, permission_key='view',
            )
            if not allowed:
                return jsonify({'success': False, 'error': deny_msg or 'Permission denied'}), 403
            _ensure_document_action_verifications_table()
            payload = {
                'action': 'delete',
                'doc_kind': 'drive',
                'drive_file_id': file_id,
            }
            if not _consume_case_document_action_token(cursor, session['employee_id'], case_id, payload, token):
                return jsonify({'success': False, 'error': 'Verification expired or invalid. Please try again.'}), 403
            connection.commit()

            cursor.execute("""
                SELECT c.id, c.client_id, c.tracking_number, c.filled_by_id, cl.id as client_table_id,
                       cl.full_name as client_full_name, cl.phone_number as client_phone
                FROM cases c
                LEFT JOIN clients cl ON c.client_id = cl.id
                WHERE c.id = %s
            """, (case_id,))
            case_data = cursor.fetchone()
        if not case_data:
            return jsonify({'success': False, 'error': 'Case not found'}), 404
        service = get_google_drive_service()
        if not service:
            return jsonify({'success': False, 'error': 'Google Drive not connected'}), 503
        main_folder_id = session.get('google_drive_main_folder_id')
        if not main_folder_id:
            with connection.cursor(pymysql.cursors.DictCursor) as cursor:
                cursor.execute("SELECT google_drive_main_folder_id FROM company_settings ORDER BY id DESC LIMIT 1")
                row = cursor.fetchone()
                main_folder_id = row.get('google_drive_main_folder_id') if row else None
        if not main_folder_id or not case_data.get('client_table_id'):
            return jsonify({'success': False, 'error': 'Case folder not available'}), 400
        client_folder_name = get_user_folder_name(
            case_data.get('client_phone'),
            case_data.get('client_full_name'),
            'client'
        )
        client_folder_id = get_or_create_folder(service, main_folder_id, client_folder_name)
        case_folder_name = get_case_drive_folder_name(case_data, case_id)
        case_doc_folder_id = get_or_create_folder(service, client_folder_id, case_folder_name)
        file_meta = service.files().get(fileId=file_id, fields='parents').execute()
        parents = file_meta.get('parents') or []
        if case_doc_folder_id not in parents:
            return jsonify({'success': False, 'error': 'File is not in this case folder'}), 403
        service.files().delete(fileId=file_id).execute()
        return jsonify({'success': True})
    except HttpError as e:
        print(f"Drive delete error: {e}")
        return jsonify({'success': False, 'error': 'Could not delete file from Drive'}), 500
    except Exception as e:
        print(f"Delete error: {e}")
        return jsonify({'success': False, 'error': str(e)}), 500
    finally:
        if connection:
            connection.close()

@app.route('/api/matter/<int:matter_id>/upload-document', methods=['POST'])
def upload_matter_document(matter_id):
    """Upload a document for a specific matter to Google Drive (Main -> Client -> Matter {ref})."""
    if 'employee_id' not in session:
        return jsonify({'success': False, 'error': 'Unauthorized'}), 401
    try:
        service = get_google_drive_service()
        if not service:
            connection = get_db_connection()
            if connection:
                try:
                    with connection.cursor(pymysql.cursors.DictCursor) as cursor:
                        cursor.execute("""
                            SELECT google_drive_token, google_drive_refresh_token, google_drive_token_uri, google_drive_scopes
                            FROM company_settings ORDER BY id DESC LIMIT 1
                        """)
                        settings = cursor.fetchone()
                        if settings and settings.get('google_drive_token') and settings.get('google_drive_refresh_token'):
                            scopes = json.loads(settings['google_drive_scopes']) if settings.get('google_drive_scopes') else []
                            session['google_drive_credentials'] = {
                                'token': settings['google_drive_token'],
                                'refresh_token': settings['google_drive_refresh_token'],
                                'token_uri': settings.get('google_drive_token_uri'),
                                'client_id': GOOGLE_CLIENT_ID,
                                'client_secret': GOOGLE_CLIENT_SECRET,
                                'scopes': scopes
                            }
                            service = get_google_drive_service()
                except Exception as e:
                    print(f"Error loading credentials: {e}")
                finally:
                    connection.close()
        if not service:
            return jsonify({'success': False, 'error': 'Google Drive not connected. Please connect Google Drive in Documents Settings.'}), 400
        connection = get_db_connection()
        if not connection:
            return jsonify({'success': False, 'error': 'Database connection error'}), 500

        # Fine-grained permission: upload/manage matter documents
        deny = enforce_permission(connection, 'matter_documents')
        if deny:
            return jsonify({'success': False, 'error': 'Forbidden'}), 403
        try:
            with connection.cursor(pymysql.cursors.DictCursor) as cursor:
                cursor.execute("""
                    SELECT m.id, m.matter_reference_number, m.client_id, m.client_name, m.client_phone,
                           cl.id as client_table_id, cl.full_name as client_full_name, cl.phone_number as client_phone_number
                    FROM matters m
                    LEFT JOIN clients cl ON m.client_id = cl.id
                    WHERE m.id = %s
                """, (matter_id,))
                matter_data = cursor.fetchone()
                if not matter_data:
                    return jsonify({'success': False, 'error': 'Matter not found'}), 404
                current_employee_id = session.get('employee_id')
                cursor.execute("SELECT assigned_employee_id FROM matters WHERE id = %s", (matter_id,))
                row = cursor.fetchone()
                assigned_id = row.get('assigned_employee_id') if row else None
                if assigned_id is None or str(assigned_id) != str(current_employee_id):
                    return jsonify({'success': False, 'error': 'You do not have access to this matter'}), 403
                main_folder_id = session.get('google_drive_main_folder_id')
                if not main_folder_id:
                    cursor.execute("SELECT google_drive_main_folder_id FROM company_settings ORDER BY id DESC LIMIT 1")
                    settings = cursor.fetchone()
                    if settings and settings.get('google_drive_main_folder_id'):
                        main_folder_id = settings['google_drive_main_folder_id']
                        session['google_drive_main_folder_id'] = main_folder_id
                if not main_folder_id:
                    err_str = 'Main folder not configured'
                    return jsonify({'success': False, 'error': err_str}), 400
                client_phone = matter_data.get('client_phone_number') or matter_data.get('client_phone')
                client_name = matter_data.get('client_full_name') or matter_data.get('client_name') or ''
                if client_name or client_phone:
                    client_folder_name = get_user_folder_name(client_phone, client_name, 'client')
                    client_folder_id = get_or_create_folder(service, main_folder_id, client_folder_name)
                else:
                    client_folder_id = get_or_create_folder(service, main_folder_id, 'Non-Litigation Matters')
                ref = (matter_data.get('matter_reference_number') or '').strip() or f'Matter-{matter_id}'
                ref = re.sub(r'[\\/:*?"<>|]', '_', ref)
                matter_folder_name = f"Matter {ref}"
                matter_doc_folder_id = get_or_create_folder(service, client_folder_id, matter_folder_name)
                if 'document_file' not in request.files:
                    return jsonify({'success': False, 'error': 'No file provided'}), 400
                file = request.files['document_file']
                if not file or file.filename == '':
                    return jsonify({'success': False, 'error': 'No file selected'}), 400
                if not allowed_document_file(file.filename):
                    return jsonify({'success': False, 'error': 'Invalid file type. Allowed: PDF, DOC, DOCX, JPG, JPEG, PNG'}), 400
                file_content = file.read()
                file_name = secure_filename(file.filename)
                description = request.form.get('description', '').strip()
                file_ext = file_name.rsplit('.', 1)[1].lower() if '.' in file_name else ''
                mime_types = {
                    'pdf': 'application/pdf',
                    'doc': 'application/msword',
                    'docx': 'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
                    'jpg': 'image/jpeg', 'jpeg': 'image/jpeg', 'png': 'image/png'
                }
                mime_type = mime_types.get(file_ext, 'application/octet-stream')
                file_metadata = {'name': file_name, 'parents': [matter_doc_folder_id]}
                if description:
                    file_metadata['description'] = description
                media = MediaIoBaseUpload(BytesIO(file_content), mimetype=mime_type, resumable=True)
                uploaded_file = service.files().create(
                    body=file_metadata,
                    media_body=media,
                    fields='id, name, webViewLink'
                ).execute()
                return jsonify({
                    'success': True,
                    'message': 'Document uploaded successfully',
                    'file_id': uploaded_file.get('id'),
                    'file_name': uploaded_file.get('name')
                })
        except Exception as e:
            err_str = str(e).lower()
            if 'invalid_grant' in err_str or 'expired' in err_str or 'revoked' in err_str:
                return jsonify({
                    'success': False,
                    'error': 'Google Drive session expired or revoked. Please reconnect Google Drive in Documents Settings.',
                    'settings_url': url_for('documents_settings')
                }), 400
            raise
        finally:
            connection.close()
    except Exception as e:
        print(f"Upload matter document error: {e}")
        return jsonify({'success': False, 'error': f'Upload failed: {str(e)}'}), 500

@app.route('/other_matters/<int:matter_id>/document/<file_id>/download')  # legacy
@app.route('/non_litigation_matters/<int:matter_id>/document/<file_id>/download')
def download_matter_document(matter_id, file_id):
    """Stream a matter document from Google Drive as a download."""
    if 'employee_id' not in session:
        return redirect(url_for('login'))
    token = (request.args.get('token') or '').strip()
    if not token:
        flash('Email verification is required before downloading. Please verify from the matter page.', 'error')
        return redirect(url_for('matter_details', matter_id=matter_id))
    connection = get_db_connection()
    if not connection:
        return redirect(url_for('matter_documents', matter_id=matter_id))
    try:
        with connection.cursor(pymysql.cursors.DictCursor) as cursor:
            allowed, deny_msg = _matter_document_action_allowed(cursor, matter_id, session['employee_id'])
            if not allowed:
                flash(deny_msg or 'Permission denied.', 'error')
                return redirect(url_for('other_matters'))
            _ensure_document_action_verifications_table()
            payload = {
                'action': 'download',
                'doc_kind': 'drive',
                'drive_file_id': file_id,
            }
            if not _consume_matter_document_action_token(cursor, session['employee_id'], matter_id, payload, token):
                flash('Verification expired or invalid. Please try again.', 'error')
                return redirect(url_for('matter_details', matter_id=matter_id))
            connection.commit()
    finally:
        connection.close()
    service = get_google_drive_service()
    if not service:
        flash('Google Drive is not connected.', 'error')
        return redirect(url_for('matter_documents', matter_id=matter_id))
    try:
        meta = service.files().get(fileId=file_id, fields='name,mimeType').execute()
        name = meta.get('name', 'document')
        mime = meta.get('mimeType', '')
        if mime and mime.startswith('application/vnd.google-apps.'):
            export_map = {
                'application/vnd.google-apps.document': ('application/pdf', '.pdf'),
                'application/vnd.google-apps.spreadsheet': ('application/vnd.openxmlformats-officedocument.spreadsheetml.sheet', '.xlsx'),
                'application/vnd.google-apps.presentation': ('application/pdf', '.pdf'),
            }
            exp_mime, ext = export_map.get(mime, ('application/pdf', '.pdf'))
            content = service.files().export(fileId=file_id, mimeType=exp_mime).execute()
            base_name = name.rsplit('.', 1)[0] if '.' in name else name
            download_name = base_name + ext
            return send_file(BytesIO(content), as_attachment=True, download_name=download_name, mimetype=exp_mime)
        request_dl = service.files().get_media(fileId=file_id)
        buf = BytesIO()
        downloader = MediaIoBaseDownload(buf, request_dl)
        done = False
        while not done:
            _, done = downloader.next_chunk()
        buf.seek(0)
        return send_file(buf, as_attachment=True, download_name=name, mimetype=mime or 'application/octet-stream')
    except HttpError as e:
        print(f"Drive download error: {e}")
        flash('Could not download file from Google Drive.', 'error')
        return redirect(url_for('matter_documents', matter_id=matter_id))
    except Exception as e:
        print(f"Download error: {e}")
        flash('Download failed.', 'error')
        return redirect(url_for('matter_documents', matter_id=matter_id))

@app.route('/api/matter/<int:matter_id>/document/<file_id>/delete', methods=['POST', 'DELETE'])
def delete_matter_document_api(matter_id, file_id):
    """Delete a matter document from Google Drive. File must be in the matter's folder."""
    if 'employee_id' not in session:
        return jsonify({'success': False, 'error': 'Unauthorized'}), 401
    data = request.get_json(silent=True) or request.form
    token = (data.get('token') or request.args.get('token') or '').strip()
    if not token:
        return jsonify({'success': False, 'error': 'Email verification is required before deleting.'}), 403
    connection = get_db_connection()
    if not connection:
        return jsonify({'success': False, 'error': 'Database error'}), 500
    try:
        with connection.cursor(pymysql.cursors.DictCursor) as cursor:
            allowed, deny_msg = _matter_document_action_allowed(cursor, matter_id, session['employee_id'])
            if not allowed:
                return jsonify({'success': False, 'error': deny_msg or 'Permission denied'}), 403
            _ensure_document_action_verifications_table()
            payload = {
                'action': 'delete',
                'doc_kind': 'drive',
                'drive_file_id': file_id,
            }
            if not _consume_matter_document_action_token(cursor, session['employee_id'], matter_id, payload, token):
                return jsonify({'success': False, 'error': 'Verification expired or invalid. Please try again.'}), 403
            connection.commit()

            cursor.execute("""
                SELECT m.id, m.matter_reference_number, m.assigned_employee_id,
                       m.client_id, cl.full_name as client_full_name, cl.phone_number as client_phone_number,
                       m.client_name as matter_client_name, m.client_phone as matter_client_phone
                FROM matters m
                LEFT JOIN clients cl ON m.client_id = cl.id
                WHERE m.id = %s
            """, (matter_id,))
            matter_data = cursor.fetchone()
        if not matter_data:
            return jsonify({'success': False, 'error': 'Matter not found'}), 404
        service = get_google_drive_service()
        if not service:
            return jsonify({'success': False, 'error': 'Google Drive not connected'}), 503
        main_folder_id = session.get('google_drive_main_folder_id')
        if not main_folder_id:
            with connection.cursor(pymysql.cursors.DictCursor) as cursor:
                cursor.execute("SELECT google_drive_main_folder_id FROM company_settings ORDER BY id DESC LIMIT 1")
                row = cursor.fetchone()
                main_folder_id = row.get('google_drive_main_folder_id') if row else None
        if not main_folder_id:
            return jsonify({'success': False, 'error': 'Matter folder not available'}), 400
        client_phone = matter_data.get('client_phone_number') or matter_data.get('matter_client_phone')
        client_name = matter_data.get('client_full_name') or matter_data.get('matter_client_name') or ''
        if client_name or client_phone:
            client_folder_name = get_user_folder_name(client_phone, client_name, 'client')
            client_folder_id = get_or_create_folder(service, main_folder_id, client_folder_name)
        else:
            client_folder_id = get_or_create_folder(service, main_folder_id, 'Non-Litigation Matters')
        ref = (matter_data.get('matter_reference_number') or '').strip() or f'Matter-{matter_id}'
        ref = re.sub(r'[\\/:*?"<>|]', '_', ref)
        matter_folder_name = f"Matter {ref}"
        matter_doc_folder_id = get_or_create_folder(service, client_folder_id, matter_folder_name)
        file_meta = service.files().get(fileId=file_id, fields='parents').execute()
        parents = file_meta.get('parents') or []
        if matter_doc_folder_id not in parents:
            return jsonify({'success': False, 'error': 'File is not in this matter folder'}), 403
        service.files().delete(fileId=file_id).execute()
        return jsonify({'success': True})
    except HttpError as e:
        print(f"Drive delete error: {e}")
        return jsonify({'success': False, 'error': 'Could not delete file from Drive'}), 500
    except Exception as e:
        print(f"Delete matter document error: {e}")
        return jsonify({'success': False, 'error': str(e)}), 500
    finally:
        if connection:
            connection.close()

@app.route('/documents_settings')
def documents_settings():
    """Documents Settings page"""
    if 'employee_id' not in session:
        return redirect(url_for('login'))
    
    user_role = session.get('employee_role')
    original_role = session.get('original_role')
    allowed_roles = ['IT Support', 'Firm Administrator', 'Managing Partner']
    has_permission = (user_role in allowed_roles) or (original_role == 'IT Support')
    
    if not has_permission:
        flash('You do not have permission to access this page', 'error')
        return redirect(url_for('dashboard'))
    
    # Load Google Drive credentials from database into session if not already loaded
    if 'google_drive_credentials' not in session:
        connection = get_db_connection()
        if connection:
            try:
                with connection.cursor(pymysql.cursors.DictCursor) as cursor:
                    cursor.execute("""
                        SELECT google_drive_token, google_drive_refresh_token, google_drive_token_uri,
                               google_drive_scopes, google_drive_account_email, google_drive_account_name,
                               google_drive_account_picture, google_drive_main_folder_id
                        FROM company_settings 
                        ORDER BY id DESC LIMIT 1
                    """)
                    settings = cursor.fetchone()
                    
                    if settings and settings.get('google_drive_token') and settings.get('google_drive_refresh_token'):
                        scopes = json.loads(settings['google_drive_scopes']) if settings.get('google_drive_scopes') else []
                        session['google_drive_credentials'] = {
                            'token': settings['google_drive_token'],
                            'refresh_token': settings['google_drive_refresh_token'],
                            'token_uri': settings.get('google_drive_token_uri'),
                            'client_id': GOOGLE_CLIENT_ID,
                            'client_secret': GOOGLE_CLIENT_SECRET,
                            'scopes': scopes
                        }
                        session['google_drive_account'] = {
                            'email': settings.get('google_drive_account_email'),
                            'name': settings.get('google_drive_account_name'),
                            'picture': settings.get('google_drive_account_picture')
                        }
                        if settings.get('google_drive_main_folder_id'):
                            session['google_drive_main_folder_id'] = settings['google_drive_main_folder_id']
            except Exception as e:
                print(f"Error loading Google Drive credentials: {e}")
            finally:
                connection.close()
    
    company_settings = get_company_settings()
    if not company_settings:
        company_settings = {'company_name': 'SHERIA LAW FIRM'}

    # Fine-grained permission: manage document settings
    connection = get_db_connection()
    if connection:
        deny = enforce_permission(connection, 'system_manage_document_settings')
        connection.close()
        if deny:
            return deny

    # Compute fresh Drive connection state so the template can render the
    # right card (connected / needs reconnect / never connected) without
    # an extra round-trip and so the global banner stays in sync.
    drive_state = evaluate_drive_connection_state()
    refresh_drive_login_notice()

    return render_template(
        'documents_settings.html',
        company_settings=company_settings,
        drive_state=drive_state,
    )

@app.route('/view_client_documents/<int:client_id>')
def view_client_documents(client_id):
    """View documents for a specific client"""
    if 'employee_id' not in session:
        return redirect(url_for('login'))
    
    user_role = session.get('employee_role')
    original_role = session.get('original_role')
    allowed_roles = ['IT Support', 'Firm Administrator', 'Managing Partner', 'Clerk']
    has_permission = (user_role in allowed_roles) or (original_role == 'IT Support')
    
    if not has_permission:
        flash('You do not have permission to access this page', 'error')
        return redirect(url_for('dashboard'))
    
    connection = get_db_connection()
    if not connection:
        flash('Database connection error.', 'error')
        return redirect(url_for('document_management'))
    
    try:
        with connection.cursor(pymysql.cursors.DictCursor) as cursor:
            cursor.execute("""
                SELECT 
                    id,
                    google_id,
                    full_name,
                    email,
                    phone_number,
                    profile_picture,
                    client_type,
                    status,
                    created_at,
                    id_front,
                    id_back,
                    instruction_note,
                    cr12_certificate,
                    corporate_kra_pin
                FROM clients
                WHERE id = %s
            """, (client_id,))
            client = cursor.fetchone()
            
            if not client:
                flash('Client not found', 'error')
                return redirect(url_for('document_management'))
            
            if client.get('created_at'):
                client['created_at'] = client['created_at'].strftime('%Y-%m-%d %H:%M:%S')

            personal_uploads, custom_uploads = _build_client_registration_documents(client, client_id, cursor)

            google_drive_connected = False
            client_folder_name = get_user_folder_name(client.get('phone_number'), client.get('full_name'), 'client')
            drive_tree = []
            drive_file_count = 0
            drive_folder_count = 0

            cursor.execute("""
                SELECT google_drive_token, google_drive_refresh_token, google_drive_token_uri,
                       google_drive_scopes, google_drive_main_folder_id
                FROM company_settings ORDER BY id DESC LIMIT 1
            """)
            drive_settings = cursor.fetchone()
            if drive_settings and drive_settings.get('google_drive_token') and drive_settings.get('google_drive_refresh_token'):
                google_drive_connected = True

            if google_drive_connected:
                try:
                    scopes = json.loads(drive_settings['google_drive_scopes']) if drive_settings.get('google_drive_scopes') else []
                    credentials = Credentials(
                        token=drive_settings['google_drive_token'],
                        refresh_token=drive_settings['google_drive_refresh_token'],
                        token_uri=drive_settings.get('google_drive_token_uri'),
                        client_id=GOOGLE_CLIENT_ID,
                        client_secret=GOOGLE_CLIENT_SECRET,
                        scopes=scopes,
                    )
                    ok, _info = refresh_drive_credentials_safely(credentials, cursor, connection)
                    if not ok:
                        raise RefreshError('invalid_grant: Google Drive needs reconnect')
                    service = build('drive', 'v3', credentials=credentials)
                    main_folder_id = drive_settings.get('google_drive_main_folder_id')
                    if service and main_folder_id:
                        client_folder_id = find_drive_folder(service, main_folder_id, client_folder_name)
                        if client_folder_id:
                            drive_tree = build_drive_folder_tree(service, client_folder_id)

                            def _count_nodes(nodes):
                                files = 0
                                folders = 0
                                for node in nodes:
                                    if node['type'] == 'folder':
                                        folders += 1
                                        f, d = _count_nodes(node.get('children', []))
                                        files += f
                                        folders += d
                                    else:
                                        files += 1
                                return files, folders

                            drive_file_count, drive_folder_count = _count_nodes(drive_tree)
                except Exception as e:
                    print(f"Error fetching client Drive tree: {e}")
                    import traceback
                    traceback.print_exc()
            
            company_settings = get_company_settings()
            if not company_settings:
                company_settings = {'company_name': 'SHERIA LAW FIRM'}
            
            return render_template('view_client_documents.html',
                                 client=client,
                                 client_id=client_id,
                                 company_settings=company_settings,
                                 personal_uploads=personal_uploads,
                                 custom_uploads=custom_uploads,
                                 google_drive_connected=google_drive_connected,
                                 client_folder_name=client_folder_name,
                                 drive_tree=drive_tree,
                                 drive_file_count=drive_file_count,
                                 drive_folder_count=drive_folder_count)
    except Exception as e:
        print(f"Error fetching client documents: {e}")
        flash('An error occurred while fetching client information.', 'error')
        return redirect(url_for('document_management'))
    finally:
        connection.close()


@app.route('/api/staff/client_documents/<int:client_id>/action/send-code', methods=['POST'])
def staff_client_document_send_code(client_id):
    """Send a verification code to the logged-in employee's email before download/delete."""
    if not _staff_can_manage_client_documents():
        return jsonify({'success': False, 'error': 'Unauthorized'}), 401

    _ensure_document_action_verifications_table()
    data = request.get_json(silent=True) or request.form
    payload, err = _parse_staff_document_action_payload(data)
    if err:
        return jsonify({'success': False, 'error': err}), 400

    connection = get_db_connection()
    if not connection:
        return jsonify({'success': False, 'error': 'Database connection error'}), 500

    try:
        from datetime import datetime as _dt, timedelta as _td
        with connection.cursor(pymysql.cursors.DictCursor) as cursor:
            cursor.execute("SELECT id FROM clients WHERE id = %s", (client_id,))
            if not cursor.fetchone():
                return jsonify({'success': False, 'error': 'Client not found'}), 404

            employee_id = session['employee_id']
            cursor.execute("""
                SELECT id, full_name, work_email, personal_email
                FROM employees WHERE id = %s
            """, (employee_id,))
            employee = cursor.fetchone()
            if not employee:
                return jsonify({'success': False, 'error': 'Employee not found'}), 404

            delivery_email = (employee.get('personal_email') or employee.get('work_email') or '').strip()
            if not delivery_email:
                return jsonify({'success': False, 'error': 'No registered email on your account. Contact your administrator.'}), 400

            cursor.execute("""
                UPDATE document_action_verifications SET used = 1
                WHERE employee_id = %s AND client_id = %s AND used = 0
            """, (employee_id, client_id))

            code = f"{secrets.randbelow(1_000_000):06d}"
            code_hash = generate_password_hash(code)
            expires_at = _dt.utcnow() + _td(minutes=10)

            cursor.execute("""
                INSERT INTO document_action_verifications
                    (employee_id, client_id, action, doc_kind, doc_field, doc_id, drive_file_id, code_hash, expires_at)
                VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s)
            """, (
                employee_id, client_id,
                payload['action'], payload['doc_kind'],
                payload.get('doc_field'), payload.get('doc_id'), payload.get('drive_file_id'),
                code_hash, expires_at,
            ))
            connection.commit()

        action_label = 'Download document' if payload['action'] == 'download' else 'Delete document'
        sent = _send_document_action_code_email(delivery_email, code, employee.get('full_name'), action_label)
        if not sent:
            return jsonify({'success': False, 'error': 'Could not send verification email. Try again later.'}), 500

        return jsonify({
            'success': True,
            'message': f'A verification code has been sent to {_mask_email_address(delivery_email)}.',
            'delivery_email': _mask_email_address(delivery_email),
            'expires_in_minutes': 10,
        })
    except Exception as e:
        print(f"[staff_client_document_send_code] error: {e}")
        return jsonify({'success': False, 'error': 'Something went wrong. Please try again.'}), 500
    finally:
        connection.close()


@app.route('/api/staff/client_documents/<int:client_id>/action/verify-code', methods=['POST'])
def staff_client_document_verify_code(client_id):
    """Verify the emailed code and return a short-lived one-time action token."""
    if not _staff_can_manage_client_documents():
        return jsonify({'success': False, 'error': 'Unauthorized'}), 401

    _ensure_document_action_verifications_table()
    data = request.get_json(silent=True) or request.form
    payload, err = _parse_staff_document_action_payload(data)
    if err:
        return jsonify({'success': False, 'error': err}), 400

    code = (data.get('code') or '').strip()
    if not code.isdigit() or len(code) != 6:
        return jsonify({'success': False, 'error': 'Code must be 6 digits.'}), 400

    connection = get_db_connection()
    if not connection:
        return jsonify({'success': False, 'error': 'Database connection error'}), 500

    try:
        from datetime import datetime as _dt, timedelta as _td
        with connection.cursor(pymysql.cursors.DictCursor) as cursor:
            employee_id = session['employee_id']
            cursor.execute("""
                SELECT id, code_hash, expires_at, used
                FROM document_action_verifications
                WHERE employee_id = %s AND client_id = %s
                  AND action = %s AND doc_kind = %s
                  AND (doc_field <=> %s) AND (doc_id <=> %s) AND (drive_file_id <=> %s)
                  AND used = 0
                ORDER BY id DESC
                LIMIT 1
            """, (
                employee_id, client_id,
                payload['action'], payload['doc_kind'],
                payload.get('doc_field'), payload.get('doc_id'), payload.get('drive_file_id'),
            ))
            row = cursor.fetchone()
            if not row:
                return jsonify({'success': False, 'error': 'Invalid or expired code. Request a new one.'}), 400
            if row.get('expires_at') and row['expires_at'] < _dt.utcnow():
                return jsonify({'success': False, 'error': 'Code expired. Please request a new one.'}), 400
            if not check_password_hash(row['code_hash'], code):
                return jsonify({'success': False, 'error': 'Incorrect verification code.'}), 400

            action_token = secrets.token_urlsafe(32)
            token_hash = generate_password_hash(action_token)
            verified_at = _dt.utcnow()
            token_expires_at = verified_at + _td(minutes=5)

            cursor.execute("""
                UPDATE document_action_verifications
                SET verified_at = %s, action_token_hash = %s, token_expires_at = %s
                WHERE id = %s
            """, (verified_at, token_hash, token_expires_at, row['id']))
            connection.commit()

        return jsonify({
            'success': True,
            'message': 'Code verified.',
            'action_token': action_token,
            'expires_in_minutes': 5,
        })
    except Exception as e:
        print(f"[staff_client_document_verify_code] error: {e}")
        return jsonify({'success': False, 'error': 'Something went wrong. Please try again.'}), 500
    finally:
        connection.close()


@app.route('/api/staff/client_documents/<int:client_id>/action/verify-password', methods=['POST'])
def staff_client_document_verify_password(client_id):
    """Confirm the logged-in employee's password and return a short-lived action token."""
    if not _staff_can_manage_client_documents():
        return jsonify({'success': False, 'error': 'Unauthorized'}), 401

    _ensure_document_action_verifications_table()
    data = request.get_json(silent=True) or request.form
    payload, err = _parse_staff_document_action_payload(data)
    if err:
        return jsonify({'success': False, 'error': err}), 400

    password = (data.get('password') or '').strip()
    if not password:
        return jsonify({'success': False, 'error': 'Password is required.'}), 400

    connection = get_db_connection()
    if not connection:
        return jsonify({'success': False, 'error': 'Database connection error'}), 500

    try:
        with connection.cursor(pymysql.cursors.DictCursor) as cursor:
            cursor.execute("SELECT id FROM clients WHERE id = %s", (client_id,))
            if not cursor.fetchone():
                return jsonify({'success': False, 'error': 'Client not found'}), 404

            employee_id = session['employee_id']
            cursor.execute("SELECT password_hash FROM employees WHERE id = %s", (employee_id,))
            employee = cursor.fetchone()
            if not employee or not check_password_hash(employee['password_hash'], password):
                return jsonify({'success': False, 'error': 'Incorrect password.'}), 403

            action_token = _issue_staff_document_action_token(
                cursor, connection, employee_id, client_id, payload,
            )

        return jsonify({
            'success': True,
            'message': 'Password verified.',
            'action_token': action_token,
            'expires_in_minutes': 5,
        })
    except Exception as e:
        print(f"[staff_client_document_verify_password] error: {e}")
        return jsonify({'success': False, 'error': 'Something went wrong. Please try again.'}), 500
    finally:
        connection.close()


@app.route('/api/staff/client_documents/<int:client_id>/download', methods=['GET'])
def staff_client_document_download(client_id):
    """Download a client document after email verification."""
    if not _staff_can_manage_client_documents():
        return jsonify({'success': False, 'error': 'Unauthorized'}), 401

    _ensure_document_action_verifications_table()
    data = {
        'action': 'download',
        'doc_kind': request.args.get('doc_kind'),
        'field': request.args.get('field'),
        'doc_id': request.args.get('doc_id'),
        'drive_file_id': request.args.get('drive_file_id'),
    }
    payload, err = _parse_staff_document_action_payload(data)
    if err:
        flash(err, 'error')
        return redirect(url_for('view_client_documents', client_id=client_id))

    token = (request.args.get('token') or '').strip()
    connection = get_db_connection()
    if not connection:
        flash('Database connection error.', 'error')
        return redirect(url_for('view_client_documents', client_id=client_id))

    try:
        with connection.cursor(pymysql.cursors.DictCursor) as cursor:
            employee_id = session['employee_id']
            if not _consume_staff_document_action_token(cursor, employee_id, client_id, payload, token):
                flash('Verification expired or invalid. Please try again.', 'error')
                return redirect(url_for('view_client_documents', client_id=client_id))
            connection.commit()

            upload_folder = app.config.get('UPLOAD_FOLDER', os.path.join('static', 'uploads', 'profile_pictures'))

            if payload['doc_kind'] == 'legacy':
                field = payload['doc_field']
                cursor.execute(f"SELECT {field} FROM clients WHERE id = %s", (client_id,))
                client = cursor.fetchone()
                if not client or not client.get(field):
                    flash('Document not found.', 'error')
                    return redirect(url_for('view_client_documents', client_id=client_id))
                return send_from_directory(
                    os.path.abspath(upload_folder),
                    client[field],
                    as_attachment=True,
                )

            if payload['doc_kind'] == 'custom':
                cursor.execute("""
                    SELECT filename, original_filename
                    FROM client_personal_documents
                    WHERE id = %s AND client_id = %s
                """, (payload['doc_id'], client_id))
                doc = cursor.fetchone()
                if not doc:
                    flash('Document not found.', 'error')
                    return redirect(url_for('view_client_documents', client_id=client_id))
                return send_from_directory(
                    os.path.abspath(upload_folder),
                    doc['filename'],
                    as_attachment=True,
                    download_name=doc.get('original_filename') or doc['filename'],
                )

            service, client_folder_id = _get_client_drive_folder_context(cursor, connection, client_id)
            if not service or not client_folder_id:
                flash('Google Drive is not connected for this client.', 'error')
                return redirect(url_for('view_client_documents', client_id=client_id))

            file_id = payload['drive_file_id']
            if not _drive_file_belongs_to_folder(service, file_id, client_folder_id):
                flash('File is not in this client\'s Drive folder.', 'error')
                return redirect(url_for('view_client_documents', client_id=client_id))

            meta = service.files().get(fileId=file_id, fields='name,mimeType').execute()
            name = meta.get('name', 'document')
            mime = meta.get('mimeType', '')
            if mime and mime.startswith('application/vnd.google-apps.'):
                export_map = {
                    'application/vnd.google-apps.document': ('application/pdf', '.pdf'),
                    'application/vnd.google-apps.spreadsheet': (
                        'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet', '.xlsx'
                    ),
                    'application/vnd.google-apps.presentation': ('application/pdf', '.pdf'),
                }
                exp_mime, ext = export_map.get(mime, ('application/pdf', '.pdf'))
                content = service.files().export(fileId=file_id, mimeType=exp_mime).execute()
                base_name = name.rsplit('.', 1)[0] if '.' in name else name
                return send_file(
                    BytesIO(content), as_attachment=True,
                    download_name=base_name + ext, mimetype=exp_mime,
                )

            request_dl = service.files().get_media(fileId=file_id)
            buf = BytesIO()
            downloader = MediaIoBaseDownload(buf, request_dl)
            done = False
            while not done:
                _, done = downloader.next_chunk()
            buf.seek(0)
            return send_file(buf, as_attachment=True, download_name=name, mimetype=mime or 'application/octet-stream')
    except HttpError as e:
        print(f"[staff_client_document_download] Drive error: {e}")
        flash('Could not download file from Google Drive.', 'error')
        return redirect(url_for('view_client_documents', client_id=client_id))
    except Exception as e:
        print(f"[staff_client_document_download] error: {e}")
        flash('Download failed.', 'error')
        return redirect(url_for('view_client_documents', client_id=client_id))
    finally:
        connection.close()


@app.route('/api/staff/client_documents/<int:client_id>/delete', methods=['POST'])
def staff_client_document_delete(client_id):
    """Delete a client document after email verification."""
    if not _staff_can_manage_client_documents():
        return jsonify({'success': False, 'error': 'Unauthorized'}), 401

    _ensure_document_action_verifications_table()
    data = request.get_json(silent=True) or request.form
    token = (data.get('token') or '').strip()
    payload, err = _parse_staff_document_action_payload(data)
    if err:
        return jsonify({'success': False, 'error': err}), 400

    connection = get_db_connection()
    if not connection:
        return jsonify({'success': False, 'error': 'Database connection error'}), 500

    try:
        with connection.cursor(pymysql.cursors.DictCursor) as cursor:
            employee_id = session['employee_id']
            if not _consume_staff_document_action_token(cursor, employee_id, client_id, payload, token):
                return jsonify({'success': False, 'error': 'Verification expired or invalid. Please try again.'}), 403

            upload_folder = app.config.get('UPLOAD_FOLDER', os.path.join('static', 'uploads', 'profile_pictures'))

            if payload['doc_kind'] == 'legacy':
                field = payload['doc_field']
                cursor.execute(f"SELECT {field} FROM clients WHERE id = %s", (client_id,))
                client = cursor.fetchone()
                if not client or not client.get(field):
                    return jsonify({'success': False, 'error': 'Document not found'}), 404
                old_filename = client[field]
                cursor.execute(f"UPDATE clients SET {field} = NULL WHERE id = %s", (client_id,))
                connection.commit()
                if old_filename:
                    old_path = os.path.join(upload_folder, old_filename)
                    if os.path.exists(old_path):
                        try:
                            os.remove(old_path)
                        except Exception:
                            pass
                return jsonify({'success': True, 'message': 'Document deleted successfully'})

            if payload['doc_kind'] == 'custom':
                cursor.execute("""
                    SELECT filename FROM client_personal_documents
                    WHERE id = %s AND client_id = %s
                """, (payload['doc_id'], client_id))
                doc = cursor.fetchone()
                if not doc:
                    return jsonify({'success': False, 'error': 'Document not found'}), 404
                cursor.execute("DELETE FROM client_personal_documents WHERE id = %s AND client_id = %s",
                               (payload['doc_id'], client_id))
                connection.commit()
                old_path = os.path.join(upload_folder, doc['filename'])
                if os.path.exists(old_path):
                    try:
                        os.remove(old_path)
                    except Exception:
                        pass
                return jsonify({'success': True, 'message': 'Document deleted successfully'})

            service, client_folder_id = _get_client_drive_folder_context(cursor, connection, client_id)
            if not service or not client_folder_id:
                return jsonify({'success': False, 'error': 'Google Drive is not connected'}), 400

            file_id = payload['drive_file_id']
            if not _drive_file_belongs_to_folder(service, file_id, client_folder_id):
                return jsonify({'success': False, 'error': 'File is not in this client\'s Drive folder'}), 403

            service.files().update(fileId=file_id, body={'trashed': True}).execute()
            connection.commit()
            return jsonify({'success': True, 'message': 'Document moved to Google Drive trash'})
    except HttpError as e:
        print(f"[staff_client_document_delete] Drive error: {e}")
        return jsonify({'success': False, 'error': f'Failed to delete: {str(e)}'}), 500
    except Exception as e:
        print(f"[staff_client_document_delete] error: {e}")
        return jsonify({'success': False, 'error': 'Delete failed'}), 500
    finally:
        connection.close()


@app.route('/api/staff/client_documents/<int:client_id>/edit-open', methods=['POST'])
def staff_client_document_edit_open(client_id):
    """Consume verification token and return a Google Drive edit URL."""
    if not _staff_can_manage_client_documents():
        return jsonify({'success': False, 'error': 'Unauthorized'}), 401

    _ensure_document_action_verifications_table()
    data = request.get_json(silent=True) or request.form
    token = (data.get('token') or '').strip()
    payload, err = _parse_staff_document_action_payload(data)
    if err:
        return jsonify({'success': False, 'error': err}), 400
    if payload['action'] != 'edit' or payload['doc_kind'] != 'drive':
        return jsonify({'success': False, 'error': 'Invalid edit request.'}), 400

    connection = get_db_connection()
    if not connection:
        return jsonify({'success': False, 'error': 'Database connection error'}), 500

    try:
        with connection.cursor(pymysql.cursors.DictCursor) as cursor:
            employee_id = session['employee_id']
            if not _consume_staff_document_action_token(cursor, employee_id, client_id, payload, token):
                return jsonify({'success': False, 'error': 'Verification expired or invalid. Please try again.'}), 403
            connection.commit()

            service, client_folder_id = _get_client_drive_folder_context(cursor, connection, client_id)
            if not service or not client_folder_id:
                return jsonify({'success': False, 'error': 'Google Drive is not connected'}), 400

            file_id = payload['drive_file_id']
            if not _drive_file_belongs_to_folder(service, file_id, client_folder_id):
                return jsonify({'success': False, 'error': 'File is not in this client\'s Drive folder'}), 403

            meta = service.files().get(fileId=file_id, fields='mimeType').execute()
            mime = meta.get('mimeType', '')
            edit_url = ''
            if mime == 'application/vnd.google-apps.document':
                edit_url = f'https://docs.google.com/document/d/{file_id}/edit'
            elif mime == 'application/vnd.google-apps.spreadsheet':
                edit_url = f'https://docs.google.com/spreadsheets/d/{file_id}/edit'
            elif mime == 'application/vnd.google-apps.presentation':
                edit_url = f'https://docs.google.com/presentation/d/{file_id}/edit'
            else:
                return jsonify({'success': False, 'error': 'This file type cannot be edited online. Replace it instead.'}), 400

        return jsonify({'success': True, 'edit_url': edit_url})
    except HttpError as e:
        print(f"[staff_client_document_edit_open] Drive error: {e}")
        return jsonify({'success': False, 'error': 'Could not open document for editing.'}), 500
    except Exception as e:
        print(f"[staff_client_document_edit_open] error: {e}")
        return jsonify({'success': False, 'error': 'Something went wrong. Please try again.'}), 500
    finally:
        connection.close()


@app.route('/api/staff/client_documents/<int:client_id>/update', methods=['POST'])
def staff_client_document_update(client_id):
    """Replace a client registration or personal document after email verification."""
    if not _staff_can_manage_client_documents():
        return jsonify({'success': False, 'error': 'Unauthorized'}), 401

    _ensure_document_action_verifications_table()
    token = (request.form.get('token') or '').strip()
    data = {
        'action': 'edit',
        'doc_kind': request.form.get('doc_kind'),
        'field': request.form.get('field'),
        'doc_id': request.form.get('doc_id'),
        'drive_file_id': request.form.get('drive_file_id'),
    }
    payload, err = _parse_staff_document_action_payload(data)
    if err:
        return jsonify({'success': False, 'error': err}), 400

    if 'document_file' not in request.files:
        return jsonify({'success': False, 'error': 'No file provided'}), 400
    file = request.files['document_file']
    if not file or not file.filename:
        return jsonify({'success': False, 'error': 'No file selected'}), 400

    connection = get_db_connection()
    if not connection:
        return jsonify({'success': False, 'error': 'Database connection error'}), 500

    try:
        with connection.cursor(pymysql.cursors.DictCursor) as cursor:
            employee_id = session['employee_id']
            if not _consume_staff_document_action_token(cursor, employee_id, client_id, payload, token):
                return jsonify({'success': False, 'error': 'Verification expired or invalid. Please try again.'}), 403

            upload_folder = app.config.get('UPLOAD_FOLDER', os.path.join('static', 'uploads', 'profile_pictures'))

            if payload['doc_kind'] == 'legacy':
                field = payload['doc_field']
                cursor.execute(f"SELECT {field} FROM clients WHERE id = %s", (client_id,))
                client = cursor.fetchone()
                if not client:
                    return jsonify({'success': False, 'error': 'Client not found'}), 404

                old_filename = client.get(field)
                original_filename = secure_filename(file.filename)
                file_ext = original_filename.rsplit('.', 1)[1].lower() if '.' in original_filename else 'bin'
                unique_filename = f"{field}_{client_id}_{secrets.token_hex(8)}.{file_ext}"
                filepath = os.path.join(upload_folder, unique_filename)
                file.save(filepath)

                cursor.execute(f"UPDATE clients SET {field} = %s WHERE id = %s", (unique_filename, client_id))
                connection.commit()

                if old_filename:
                    old_path = os.path.join(upload_folder, old_filename)
                    if os.path.exists(old_path):
                        try:
                            os.remove(old_path)
                        except Exception:
                            pass
                return jsonify({'success': True, 'message': 'Document replaced successfully'})

            if payload['doc_kind'] == 'custom':
                cursor.execute("""
                    SELECT filename FROM client_personal_documents
                    WHERE id = %s AND client_id = %s
                """, (payload['doc_id'], client_id))
                doc = cursor.fetchone()
                if not doc:
                    return jsonify({'success': False, 'error': 'Document not found'}), 404

                old_filename = doc['filename']
                original_filename = secure_filename(file.filename)
                file_ext = original_filename.rsplit('.', 1)[1].lower() if '.' in original_filename else 'bin'
                unique_filename = f"personal_doc_{client_id}_{secrets.token_hex(8)}.{file_ext}"
                filepath = os.path.join(upload_folder, unique_filename)
                file.save(filepath)
                file_size = os.path.getsize(filepath) if os.path.exists(filepath) else 0

                cursor.execute("""
                    UPDATE client_personal_documents
                    SET filename = %s, original_filename = %s, file_size = %s
                    WHERE id = %s AND client_id = %s
                """, (unique_filename, original_filename, file_size, payload['doc_id'], client_id))
                connection.commit()

                old_path = os.path.join(upload_folder, old_filename)
                if os.path.exists(old_path):
                    try:
                        os.remove(old_path)
                    except Exception:
                        pass
                return jsonify({'success': True, 'message': 'Document replaced successfully'})

            return jsonify({'success': False, 'error': 'Unsupported document type for replace.'}), 400
    except Exception as e:
        print(f"[staff_client_document_update] error: {e}")
        return jsonify({'success': False, 'error': 'Update failed'}), 500
    finally:
        connection.close()


@app.route('/view_client_documents/<int:client_id>/<document_type>')
def view_client_document_type(client_id, document_type):
    """View documents for a specific client by document type"""
    if 'employee_id' not in session:
        return redirect(url_for('login'))
    
    user_role = session.get('employee_role')
    original_role = session.get('original_role')
    allowed_roles = ['IT Support', 'Firm Administrator', 'Managing Partner', 'Clerk']
    has_permission = (user_role in allowed_roles) or (original_role == 'IT Support')
    
    if not has_permission:
        flash('You do not have permission to access this page', 'error')
        return redirect(url_for('dashboard'))
    
    # Validate document type
    valid_types = ['CLIENT_PERSONAL_DOCUMENT', 'CLIENT_CASE_DOCUMENT', 'CLIENT_OTHER_MATTERS']
    if document_type not in valid_types:
        flash('Invalid document type', 'error')
        return redirect(url_for('view_client_documents', client_id=client_id))
    
    connection = get_db_connection()
    if not connection:
        flash('Database connection error.', 'error')
        return redirect(url_for('document_management'))
    
    # Handle CLIENT_OTHER_MATTERS differently - show matters instead of documents
    if document_type == 'CLIENT_OTHER_MATTERS':
        try:
            with connection.cursor(pymysql.cursors.DictCursor) as cursor:
                # Fetch client details
                cursor.execute("""
                    SELECT 
                        id,
                        google_id,
                        full_name,
                        email,
                        phone_number,
                        profile_picture,
                        client_type,
                        status,
                        created_at
                    FROM clients
                    WHERE id = %s
                """, (client_id,))
                client = cursor.fetchone()
                
                if not client:
                    flash('Client not found', 'error')
                    return redirect(url_for('document_management'))
                
                # Fetch all matters for this client
                cursor.execute("""
                    SELECT 
                        m.id,
                        m.matter_reference_number,
                        m.matter_title,
                        m.matter_category,
                        m.client_instructions,
                        m.assigned_employee_name,
                        m.date_opened,
                        m.status,
                        m.created_at,
                        m.updated_at
                    FROM matters m
                    WHERE m.client_id = %s
                    ORDER BY m.date_opened DESC, m.created_at DESC
                """, (client_id,))
                matters = cursor.fetchall()
                
                # Convert date objects to strings
                if client.get('created_at'):
                    client['created_at'] = client['created_at'].strftime('%Y-%m-%d %H:%M:%S')
                
                for matter in matters:
                    if matter.get('date_opened'):
                        matter['date_opened'] = matter['date_opened'].strftime('%Y-%m-%d') if hasattr(matter['date_opened'], 'strftime') else str(matter['date_opened'])
                    if matter.get('created_at'):
                        matter['created_at'] = matter['created_at'].strftime('%Y-%m-%d %H:%M:%S') if hasattr(matter['created_at'], 'strftime') else str(matter['created_at'])
                    if matter.get('updated_at'):
                        matter['updated_at'] = matter['updated_at'].strftime('%Y-%m-%d %H:%M:%S') if hasattr(matter['updated_at'], 'strftime') else str(matter['updated_at'])
                
                company_settings = get_company_settings()
                if not company_settings:
                    company_settings = {'company_name': 'SHERIA LAW FIRM'}
                
                return render_template('view_client_other_matters.html',
                                     client=client,
                                     client_id=client_id,
                                     document_type=document_type,
                                     document_type_name='Non-Litigation Matters',
                                     matters=matters,
                                     company_settings=company_settings)
        except Exception as e:
            print(f"Error fetching client matters: {e}")
            flash('An error occurred while fetching client matters.', 'error')
            return redirect(url_for('view_client_documents', client_id=client_id))
        finally:
            connection.close()
    
    try:
        with connection.cursor(pymysql.cursors.DictCursor) as cursor:
            cursor.execute("""
                SELECT id, google_id, full_name, email, phone_number, profile_picture,
                       client_type, status, created_at,
                       id_front, id_back, instruction_note, cr12_certificate, corporate_kra_pin
                FROM clients WHERE id = %s
            """, (client_id,))
            client = cursor.fetchone()
            
            if not client:
                flash('Client not found', 'error')
                return redirect(url_for('document_management'))
            
            if client.get('created_at'):
                client['created_at'] = client['created_at'].strftime('%Y-%m-%d %H:%M:%S')

            personal_uploads, custom_uploads = _build_client_registration_documents(client, client_id, cursor)
            if document_type != 'CLIENT_PERSONAL_DOCUMENT':
                personal_uploads = []
                custom_uploads = []

            document_type_names = {
                'CLIENT_PERSONAL_DOCUMENT': 'Personal Documents',
                'CLIENT_CASE_DOCUMENT': 'Case Documents'
            }
            document_type_name = document_type_names.get(document_type, document_type)

            google_drive_connected = False
            drive_tree = []
            client_folder_name = get_user_folder_name(client.get('phone_number'), client.get('full_name'), 'client')

            cursor.execute("""
                SELECT google_drive_token, google_drive_refresh_token, google_drive_token_uri,
                       google_drive_scopes, google_drive_main_folder_id
                FROM company_settings ORDER BY id DESC LIMIT 1
            """)
            drive_settings = cursor.fetchone()
            if drive_settings and drive_settings.get('google_drive_token') and drive_settings.get('google_drive_refresh_token'):
                google_drive_connected = True

            if google_drive_connected:
                try:
                    scopes = json.loads(drive_settings['google_drive_scopes']) if drive_settings.get('google_drive_scopes') else []
                    credentials = Credentials(
                        token=drive_settings['google_drive_token'],
                        refresh_token=drive_settings['google_drive_refresh_token'],
                        token_uri=drive_settings.get('google_drive_token_uri'),
                        client_id=GOOGLE_CLIENT_ID,
                        client_secret=GOOGLE_CLIENT_SECRET,
                        scopes=scopes,
                    )
                    ok, _info = refresh_drive_credentials_safely(credentials, cursor, connection)
                    if not ok:
                        raise RefreshError('invalid_grant: Google Drive needs reconnect')
                    service = build('drive', 'v3', credentials=credentials)
                    main_folder_id = drive_settings.get('google_drive_main_folder_id')
                    if service and main_folder_id:
                        client_folder_id = find_drive_folder(service, main_folder_id, client_folder_name)
                        if client_folder_id:
                            if document_type == 'CLIENT_CASE_DOCUMENT':
                                reserved = {'CLIENT_PERSONAL_DOCUMENT'}
                                for child in list_drive_folder_children(service, client_folder_id):
                                    if child.get('mimeType') != 'application/vnd.google-apps.folder':
                                        continue
                                    name = child.get('name', '')
                                    if name in reserved:
                                        continue
                                    drive_tree.extend(build_drive_folder_tree(service, child['id']))
                            else:
                                type_folder_id = find_drive_folder(service, client_folder_id, document_type)
                                if type_folder_id:
                                    drive_tree = build_drive_folder_tree(service, type_folder_id)
                except Exception as e:
                    print(f"Error fetching client document type from Drive: {e}")
                    import traceback
                    traceback.print_exc()
            
            company_settings = get_company_settings()
            if not company_settings:
                company_settings = {'company_name': 'SHERIA LAW FIRM'}
            
            return render_template('view_client_document_type.html',
                                 client=client,
                                 client_id=client_id,
                                 document_type=document_type,
                                 document_type_name=document_type_name,
                                 company_settings=company_settings,
                                 personal_uploads=personal_uploads,
                                 custom_uploads=custom_uploads,
                                 google_drive_connected=google_drive_connected,
                                 client_folder_name=client_folder_name,
                                 drive_tree=drive_tree)
    except Exception as e:
        print(f"Error fetching client documents: {e}")
        flash('An error occurred while fetching client information.', 'error')
        return redirect(url_for('document_management'))
    finally:
        connection.close()

