def _format_calendar_proceeding(proceeding, today=None):
    """Normalize proceeding date fields for calendar templates."""
    if proceeding.get('date_of_court_appeared'):
        proceeding['date_of_court_appeared'] = proceeding['date_of_court_appeared'].strftime('%Y-%m-%d')
    if proceeding.get('next_court_date'):
        next_date = proceeding['next_court_date']
        proceeding['next_court_date'] = next_date.strftime('%Y-%m-%d')
        if today is not None:
            proceeding['days_until'] = (next_date - today).days
    if proceeding.get('created_at'):
        proceeding['created_at'] = proceeding['created_at'].strftime('%Y-%m-%d %H:%M:%S')
    proceeding['source'] = 'case'
    return proceeding


def _format_calendar_matter(matter, today=None):
    """Normalize matter date fields for calendar templates."""
    if matter.get('date_opened'):
        d = matter['date_opened']
        matter['date_opened'] = d.strftime('%Y-%m-%d')
        if today is not None:
            matter['days_until'] = (d - today).days
    matter['source'] = 'matter'
    return matter


def _build_firm_calendar_events(upcoming_proceedings, all_proceedings, matters, include_past_appearances=True):
    """Build date-keyed event map matching case_calendar format."""
    calendar_events = {}

    for proceeding in upcoming_proceedings:
        key = proceeding.get('next_court_date')
        if key:
            calendar_events.setdefault(key, []).append({
                'type': 'next',
                'source': 'case',
                'proceeding': proceeding,
            })

    if include_past_appearances:
        for proceeding in all_proceedings:
            key = proceeding.get('date_of_court_appeared')
            if key:
                calendar_events.setdefault(key, []).append({
                    'type': 'appeared',
                    'source': 'case',
                    'proceeding': proceeding,
                })

    for matter in matters:
        key = matter.get('date_opened')
        if key:
            calendar_events.setdefault(key, []).append({
                'type': 'matter',
                'source': 'matter',
                'matter': matter,
            })

    return calendar_events


def _build_calendar_events_dict(proceedings, matters):
    """Build date-keyed event map for the shared calendar view (legacy flat format)."""
    calendar_events = {}
    for proceeding in proceedings:
        key = proceeding.get('next_court_date')
        if key:
            calendar_events.setdefault(key, []).append(proceeding)
    for matter in matters:
        key = matter.get('date_opened')
        if key:
            calendar_events.setdefault(key, []).append(matter)
    return calendar_events


def _calendar_item_allocated_to_employee(item, employee_id):
    """True when a case or matter row belongs to the signed-in employee."""
    if not employee_id:
        return False
    emp = str(employee_id)
    if item.get('source') == 'case':
        return str(item.get('filled_by_id') or '') == emp
    if item.get('source') == 'matter':
        return str(item.get('assigned_employee_id') or '') == emp
    return False


@app.route('/calendar')
def calendar():
    """Calendar page - displays all upcoming court dates (cases) and matter dates"""
    if 'employee_id' not in session:
        return redirect(url_for('login'))
    
    user_role = session.get('employee_role')
    original_role = session.get('original_role')
    allowed_roles = ['IT Support', 'Firm Administrator', 'Managing Partner', 'Clerk']
    has_permission = (user_role in allowed_roles) or (original_role == 'IT Support')
    
    if not has_permission:
        flash('You do not have permission to access this page', 'error')
        return redirect(url_for('dashboard'))
    
    connection = get_db_connection()
    if not connection:
        flash('Database connection error.', 'error')
        return redirect(url_for('dashboard'))

    deny = enforce_permission(connection, 'calendar_shared')
    if deny:
        return deny
    
    try:
        from datetime import date
        today = date.today()

        proceeding_select = """
            SELECT
                p.id,
                p.case_id,
                p.court_activity_type,
                p.court_room,
                p.judicial_officer,
                p.date_of_court_appeared,
                p.next_court_date,
                p.attendance,
                p.next_attendance,
                p.next_activity_type,
                p.next_judicial_officer,
                p.virtual_link,
                p.outcome_orders,
                p.created_at,
                c.tracking_number,
                c.client_name,
                c.filled_by_id,
                c.filled_by_name,
                c.id AS case_table_id
            FROM case_proceedings p
            JOIN cases c ON p.case_id = c.id
        """
        
        with connection.cursor(pymysql.cursors.DictCursor) as cursor:
            # Upcoming court dates (future)
            cursor.execute(
                proceeding_select + """
                WHERE p.next_court_date IS NOT NULL AND p.next_court_date >= %s
                ORDER BY p.next_court_date ASC
                """,
                (today,),
            )
            all_upcoming_proceedings = list(cursor.fetchall() or [])
            for proceeding in all_upcoming_proceedings:
                _format_calendar_proceeding(proceeding, today)

            # All proceedings for appearance history and past calendar dots
            cursor.execute(
                proceeding_select + """
                WHERE p.date_of_court_appeared IS NOT NULL
                ORDER BY p.date_of_court_appeared DESC
                """,
            )
            all_proceedings = list(cursor.fetchall() or [])
            for proceeding in all_proceedings:
                _format_calendar_proceeding(proceeding, today)

            # Active matters
            cursor.execute("""
                SELECT
                    m.id,
                    m.matter_reference_number,
                    m.matter_title,
                    m.matter_category,
                    m.client_name,
                    m.assigned_employee_id,
                    m.assigned_employee_name,
                    m.date_opened,
                    m.status
                FROM matters m
                WHERE m.status NOT IN ('Closed', 'Completed')
                ORDER BY m.date_opened ASC
            """)
            all_matters = list(cursor.fetchall() or [])
            matter_events = []
            for matter in all_matters:
                matter_events.append(_format_calendar_matter(matter, today))

            calendar_events = _build_firm_calendar_events(
                all_upcoming_proceedings, all_proceedings, matter_events,
                include_past_appearances=False,
            )

            all_agenda = sorted(
                all_upcoming_proceedings + matter_events,
                key=lambda x: x.get('next_court_date') or x.get('date_opened') or ''
            )

            employee_id = session.get('employee_id')
            show_scope_toggle = user_role == 'Managing Partner'
            calendar_events_mine = {}
            all_agenda_mine = []
            upcoming_mine = []
            proceedings_mine = []
            matters_mine = []
            if show_scope_toggle:
                upcoming_mine = [
                    p for p in all_upcoming_proceedings
                    if _calendar_item_allocated_to_employee(p, employee_id)
                ]
                proceedings_mine = [
                    p for p in all_proceedings
                    if _calendar_item_allocated_to_employee(p, employee_id)
                ]
                matters_mine = [
                    m for m in matter_events
                    if _calendar_item_allocated_to_employee(m, employee_id)
                ]
                calendar_events_mine = _build_firm_calendar_events(
                    upcoming_mine, proceedings_mine, matters_mine,
                    include_past_appearances=False,
                )
                all_agenda_mine = sorted(
                    upcoming_mine + matters_mine,
                    key=lambda x: x.get('next_court_date') or x.get('date_opened') or ''
                )

            company_settings = get_company_settings()
            if not company_settings:
                company_settings = {'company_name': 'SHERIA LAW FIRM'}
            
            return render_template('calendar.html', 
                                 company_settings=company_settings,
                                 all_upcoming_proceedings=all_upcoming_proceedings,
                                 upcoming_proceedings=all_upcoming_proceedings,
                                 all_proceedings=all_proceedings,
                                 calendar_events=calendar_events,
                                 calendar_events_mine=calendar_events_mine,
                                 all_agenda_mine=all_agenda_mine,
                                 upcoming_mine=upcoming_mine,
                                 proceedings_mine=proceedings_mine,
                                 matters_mine=matters_mine,
                                 show_scope_toggle=show_scope_toggle,
                                 session_employee_name=session.get('employee_name') or 'Me',
                                 matter_events=matter_events,
                                 all_agenda=all_agenda)
    except Exception as e:
        print(f"Error fetching calendar: {e}")
        flash('An error occurred while fetching calendar.', 'error')
        return redirect(url_for('dashboard'))
    finally:
        connection.close()

@app.route('/reminders')
def reminders():
    """Reminders page - displays all case reminders and all active matters"""
    if 'employee_id' not in session:
        return redirect(url_for('login'))
    
    user_role = session.get('employee_role')
    original_role = session.get('original_role')
    allowed_roles = ['IT Support', 'Firm Administrator', 'Managing Partner', 'Clerk']
    has_permission = (user_role in allowed_roles) or (original_role == 'IT Support')
    
    if not has_permission:
        flash('You do not have permission to access this page', 'error')
        return redirect(url_for('dashboard'))
    
    connection = get_db_connection()
    if not connection:
        flash('Database connection error.', 'error')
        return redirect(url_for('dashboard'))
    
    try:
        from datetime import date
        today = date.today()
        
        with connection.cursor(pymysql.cursors.DictCursor) as cursor:
            # ── Case proceedings with materials ───────────────────────────────
            cursor.execute("""
                SELECT 
                    p.id,
                    p.case_id,
                    p.court_activity_type,
                    p.court_room,
                    p.judicial_officer,
                    p.date_of_court_appeared,
                    p.next_court_date,
                    p.next_attendance,
                    p.virtual_link,
                    p.outcome_orders,
                    c.tracking_number,
                    c.client_name,
                    c.id as case_table_id
                FROM case_proceedings p
                JOIN cases c ON p.case_id = c.id
                WHERE p.next_court_date IS NOT NULL AND p.next_court_date >= %s
                ORDER BY p.next_court_date ASC
            """, (today,))
            all_upcoming_proceedings = list(cursor.fetchall() or [])

            proceedings_with_materials = []
            all_reminders = []
            for proceeding in all_upcoming_proceedings:
                if proceeding.get('date_of_court_appeared'):
                    proceeding['date_of_court_appeared'] = proceeding['date_of_court_appeared'].strftime('%Y-%m-%d')
                if proceeding.get('next_court_date'):
                    next_date = proceeding['next_court_date']
                    proceeding['next_court_date'] = next_date.strftime('%Y-%m-%d')
                    proceeding['days_until'] = (next_date - today).days
                if proceeding.get('created_at'):
                    proceeding['created_at'] = proceeding['created_at'].strftime('%Y-%m-%d %H:%M:%S')

                cursor.execute("""
                    SELECT m.id, m.proceeding_id, m.material_description,
                           m.reminder_frequency, m.allocated_to_id, m.allocated_to_name,
                           m.created_at, m.updated_at
                    FROM case_proceeding_materials m
                    WHERE m.proceeding_id = %s
                    ORDER BY m.created_at ASC
                """, (proceeding['id'],))
                materials = cursor.fetchall()
                for material in materials:
                    if material.get('created_at'):
                        material['created_at'] = material['created_at'].strftime('%Y-%m-%d %H:%M:%S')
                    if material.get('updated_at'):
                        material['updated_at'] = material['updated_at'].strftime('%Y-%m-%d %H:%M:%S')

                proceeding['materials'] = materials
                if materials:
                    proceedings_with_materials.append(proceeding)
                    all_reminders.extend(materials)

            # ── All active matters ────────────────────────────────────────────
            cursor.execute("""
                SELECT
                    m.id,
                    m.matter_reference_number,
                    m.matter_title,
                    m.matter_category,
                    m.client_name,
                    m.client_phone,
                    m.assigned_employee_id,
                    m.assigned_employee_name,
                    m.date_opened,
                    m.status,
                    m.created_at
                FROM matters m
                WHERE m.status NOT IN ('Closed', 'Completed')
                ORDER BY
                    CASE WHEN m.status = 'Pending Approval' THEN 0 ELSE 1 END ASC,
                    m.date_opened ASC
            """)
            all_matters = cursor.fetchall()
            for matter in all_matters:
                if matter.get('date_opened'):
                    d = matter['date_opened']
                    matter['date_opened'] = d.strftime('%Y-%m-%d')
                    matter['days_since_opened'] = (today - d).days
                if matter.get('created_at'):
                    matter['created_at'] = matter['created_at'].strftime('%Y-%m-%d %H:%M:%S')

            # ── Fired task reminder intervals ─────────────────────────────────
            task_due_reminders = []
            try:
                ensure_task_interval_reminders_table(cursor, connection)
                _process_due_task_reminders()
                cursor.execute("""
                    SELECT
                        r.id,
                        r.task_id,
                        r.interval_code,
                        r.task_title,
                        r.due_at,
                        r.assignee_name,
                        r.reference_label,
                        r.link_path,
                        r.fired_at
                    FROM task_interval_reminders r
                    ORDER BY r.fired_at DESC
                    LIMIT 100
                """)
                for row in cursor.fetchall() or []:
                    interval_code = (row.get('interval_code') or '').strip()
                    row['interval_label'] = TASK_REMINDER_INTERVAL_LABELS.get(
                        interval_code, interval_code or 'Reminder'
                    )
                    due_val = row.get('due_at')
                    if due_val:
                        try:
                            row['due_at'] = due_val.strftime('%Y-%m-%d %H:%M')
                        except Exception:
                            row['due_at'] = str(due_val)
                    fired = row.get('fired_at')
                    if fired:
                        try:
                            row['fired_at'] = fired.strftime('%Y-%m-%d %H:%M')
                        except Exception:
                            row['fired_at'] = str(fired)
                    task_due_reminders.append(row)
            except Exception as rem_exc:
                print(f"[reminders] task interval list error: {rem_exc}")
                task_due_reminders = []

            company_settings = get_company_settings()
            if not company_settings:
                company_settings = {'company_name': 'SHERIA LAW FIRM'}

            return render_template('reminders.html',
                                 company_settings=company_settings,
                                 proceedings_with_materials=proceedings_with_materials,
                                 all_reminders=all_reminders,
                                 all_matters=all_matters,
                                 task_due_reminders=task_due_reminders)
    except Exception as e:
        print(f"Error fetching reminders: {e}")
        flash('An error occurred while fetching reminders.', 'error')
        return redirect(url_for('dashboard'))
    finally:
        connection.close()

