@app.route('/non_litigation_matters/<int:matter_id>/edit')
def matter_edit(matter_id):
    """Matter Edit page"""
    if 'employee_id' not in session:
        return redirect(url_for('login'))
    
    connection = get_db_connection()
    if not connection:
        flash('Database connection error.', 'error')
        return redirect(url_for('other_matters'))

    # Fine-grained permission: edit matter details
    deny = enforce_permission(connection, 'matter_edit', redirect_endpoint='other_matters')
    if deny:
        return deny
    
    try:
        with connection.cursor(pymysql.cursors.DictCursor) as cursor:
            # Fetch matter details
            cursor.execute("""
                SELECT 
                    m.id,
                    m.matter_reference_number,
                    m.matter_title,
                    m.matter_category,
                    m.client_id,
                    m.client_name,
                    m.client_phone,
                    m.client_instructions,
                    m.assigned_employee_id,
                    m.assigned_employee_name,
                    m.date_opened,
                    m.status,
                    m.created_by_id,
                    m.created_by_name,
                    m.created_at,
                    m.updated_at,
                    cl.id as client_table_id,
                    cl.full_name as client_full_name,
                    cl.phone_number as client_phone_number,
                    cl.email as client_email
                FROM matters m
                LEFT JOIN clients cl ON m.client_id = cl.id
                WHERE m.id = %s
            """, (matter_id,))
            matter_data = cursor.fetchone()
            
            if not matter_data:
                flash('Matter not found', 'error')
                return redirect(url_for('other_matters'))
            
            # Convert date objects to strings
            if matter_data.get('date_opened'):
                matter_data['date_opened'] = matter_data['date_opened'].strftime('%Y-%m-%d')

            # Load parties for this matter
            cursor.execute("""
                SELECT
                    id, party_name, party_type, party_category,
                    firm_agent, party_phone, party_email
                FROM matter_parties
                WHERE matter_id = %s
                ORDER BY id ASC
            """, (matter_id,))
            parties = cursor.fetchall() or []

            cursor.execute("""
                SELECT DISTINCT matter_category
                FROM matters
                WHERE matter_category IS NOT NULL AND TRIM(matter_category) <> ''
                ORDER BY matter_category ASC
            """)
            matter_category_options = [row['matter_category'] for row in cursor.fetchall()]
            
            company_settings = get_company_settings()
            if not company_settings:
                company_settings = {'company_name': 'SHERIA LAW FIRM'}
            
            return render_template('matter_edit.html', 
                                 matter_data=matter_data, 
                                 matter_id=matter_id,
                                 parties=parties,
                                 matter_category_options=matter_category_options,
                                 company_settings=company_settings)
    except Exception as e:
        print(f"Error fetching matter for edit: {e}")
        flash('An error occurred while fetching matter details.', 'error')
        return redirect(url_for('other_matters'))
    finally:
        connection.close()

