@app.before_request
def cleanup_idle_connections_before_request():
    """Clean up idle connections before each request"""
    try:
        cleanup_idle_connections(max_idle_minutes=30)
    except:
        pass  # Don't fail requests if cleanup fails

# Initialize database on import only when explicitly enabled.
# This avoids blocking every worker start in multi-worker hosts.
if (os.environ.get('RUN_DB_INIT_ON_STARTUP', '0') or '').strip().lower() in ('1', 'true', 'yes', 'on'):
    try:
        init_database()
    except Exception as e:
        print(f"[WARNING] Database initialization failed (may be first run or DB not configured): {e}")
else:
    print("[INFO] Skipping startup DB init (set RUN_DB_INIT_ON_STARTUP=1 to enable).")

# Ensure one-shot firm seed is scheduled even if init_database returned early
try:
    _schedule_firm_defaults_seed_background()
except Exception as e:
    print(f"[WARNING] Could not schedule firm defaults seed: {e}")

try:
    start_push_notification_worker()
except Exception as e:
    print(f"[WARNING] Push notification worker failed to start: {e}")

if __name__ == '__main__':
    # Reloader is opt-in: on Windows it often false-triggers or burns CPU
    # polling site-packages, which makes every page feel stuck/slow and the
    # PWA briefly show "You're offline" during restarts.
    # Enable with: set FLASK_RELOAD=1
    use_reloader = os.environ.get('FLASK_RELOAD', '').strip().lower() in (
        '1', 'true', 'yes', 'on',
    )
    app.run(
        debug=True,
        host='0.0.0.0',
        port=5000,
        threaded=True,
        use_reloader=use_reloader,
        reloader_type='stat',
        exclude_patterns=[
            '*site-packages*',
            '*AppData*',
            '*.git*',
            '*__pycache__*',
            '*static*uploads*',
        ],
    )

